-- Aprenda se Divertindo · 93 · Baralho de cartões · trilha Fiscal · mais 500 cartões (total de 1.000)
-- Rode depois do 92-cartoes-enem-2.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Assuntos novos, conferidos contra os 4.000 cartões já existentes para não repetir: CTN (legislação, sujeição passiva,
-- lançamento, crédito, garantias), súmulas vinculantes, impostos em espécie, reforma tributária (EC 132/2023 e LC 214/2025),
-- Simples e regimes, crimes tributários; CPCs (imobilizado, intangível, estoques, receita, tributos diferidos, valor justo),
-- custos, análise, contabilidade pública; LRF, dívida, Lei 4.320; auditoria (NBC TA, COSO, setor público); economia;
-- legislação aduaneira (Duimp, valoração, NCM, regimes, infrações); estatística e fluência em dados.
-- Cartões numerados de 2.000.004.001 a 2.000.004.500. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000004001, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "Quais matérias só a lei pode estabelecer, segundo o art. 97 do CTN?", "verso": "Instituição, extinção, majoração e redução de tributos; fato gerador; alíquota e base de cálculo; penalidades; hipóteses de exclusão, suspensão e extinção do crédito.", "explicacao": "CTN, art. 97. Atualizar a base de cálculo pela inflação não é majoração (§ 2º)."}, {"id": 2000004002, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "Atualizar o valor venal do IPTU por índice oficial de inflação exige lei?", "verso": "Não. A simples atualização monetária pode ser feita por decreto; acima da inflação, exige lei.", "explicacao": "CTN, art. 97, § 2º, e Súmula 160 do STJ."}, {"id": 2000004003, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "Quando a lei tributária retroage?", "verso": "Quando é expressamente interpretativa (sem aplicar penalidade) e, em ato não definitivamente julgado, quando deixa de definir o fato como infração ou comina penalidade menos severa.", "explicacao": "CTN, art. 106."}, {"id": 2000004004, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "Qual a ordem de integração da legislação tributária na ausência de disposição expressa?", "verso": "Analogia, princípios gerais de direito tributário, princípios gerais de direito público e equidade.", "explicacao": "CTN, art. 108."}, {"id": 2000004005, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "A analogia pode ser usada para exigir tributo? E a equidade para dispensá-lo?", "verso": "Não. A analogia não pode resultar em tributo não previsto em lei, e a equidade não pode dispensar tributo devido.", "explicacao": "CTN, art. 108, §§ 1º e 2º."}, {"id": 2000004006, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "Que matérias tributárias devem ser interpretadas literalmente?", "verso": "Suspensão ou exclusão do crédito, outorga de isenção e dispensa de obrigações acessórias.", "explicacao": "CTN, art. 111."}, {"id": 2000004007, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "Em caso de dúvida sobre a infração, como se interpreta a lei tributária que define penalidades?", "verso": "Da maneira mais favorável ao acusado (in dubio pro contribuinte).", "explicacao": "CTN, art. 112."}, {"id": 2000004008, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "pergunta", "frente": "O que são normas complementares da legislação tributária?", "verso": "Atos normativos das autoridades, decisões administrativas com eficácia normativa, práticas reiteradas das autoridades e convênios entre os entes.", "explicacao": "CTN, art. 100. Observá-las exclui penalidades, juros e correção."}, {"id": 2000004009, "trilha": "fiscal", "materia": "trib", "assunto": "Fato gerador", "tipo": "pergunta", "frente": "O que é o princípio pecunia non olet?", "verso": "O tributo incide independentemente da validade jurídica ou da licitude dos atos praticados pelo contribuinte.", "explicacao": "CTN, art. 118. Ex.: renda de atividade ilícita é tributável."}, {"id": 2000004010, "trilha": "fiscal", "materia": "trib", "assunto": "Fato gerador", "tipo": "pergunta", "frente": "O que é a norma geral antielisiva do CTN?", "verso": "Permite à autoridade desconsiderar atos praticados com a finalidade de dissimular a ocorrência do fato gerador.", "explicacao": "CTN, art. 116, parágrafo único. O STF a considerou constitucional (ADI 2.446)."}, {"id": 2000004011, "trilha": "fiscal", "materia": "trib", "assunto": "Fato gerador", "tipo": "pares", "frente": "Qual a diferença entre elisão e evasão fiscal?", "verso": "Elisão: planejamento lícito para pagar menos, em geral antes do fato gerador. Evasão: uso de meios ilícitos (fraude, sonegação), em geral depois do fato gerador.", "explicacao": "Distinção doutrinária."}, {"id": 2000004012, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "O que é a solidariedade tributária e ela comporta benefício de ordem?", "verso": "São solidárias as pessoas com interesse comum no fato gerador e as designadas em lei. Não comporta benefício de ordem.", "explicacao": "CTN, art. 124."}, {"id": 2000004013, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "Quais os efeitos da solidariedade tributária?", "verso": "O pagamento por um aproveita aos demais; a isenção ou remissão exonera todos, salvo se pessoal; a interrupção da prescrição contra um atinge os demais.", "explicacao": "CTN, art. 125."}, {"id": 2000004014, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "Como fica a responsabilidade do arrematante de imóvel em hasta pública?", "verso": "Os créditos tributários do imóvel se sub-rogam no preço da arrematação: o arrematante recebe o bem livre desses débitos.", "explicacao": "CTN, art. 130, parágrafo único."}, {"id": 2000004015, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "Quem responde pelos tributos na fusão, transformação ou incorporação de empresas?", "verso": "A pessoa jurídica resultante, pelos tributos devidos até a data do ato.", "explicacao": "CTN, art. 132. A responsabilidade alcança as multas (Súmula 554 do STJ)."}, {"id": 2000004016, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "Quando o adquirente de fundo de comércio responde só subsidiariamente?", "verso": "Quando o alienante continua ou, em 6 meses, inicia nova atividade.", "explicacao": "CTN, art. 133, II. Se o alienante cessar, o adquirente responde integralmente."}, {"id": 2000004017, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "A responsabilidade de terceiros do art. 134 do CTN (pais, tutores, administradores) abrange quais multas?", "verso": "Só as de caráter moratório.", "explicacao": "CTN, art. 134, parágrafo único. Ela ocorre na impossibilidade de cobrar do contribuinte."}, {"id": 2000004018, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "A responsabilidade por infrações tributárias depende da intenção do agente?", "verso": "Não. Independe da intenção e da efetividade, natureza e extensão dos efeitos do ato, salvo disposição de lei em contrário.", "explicacao": "CTN, art. 136."}, {"id": 2000004019, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "pergunta", "frente": "Qual a regra geral do domicílio tributário da pessoa natural?", "verso": "A sua residência habitual ou, se incerta, o centro habitual de sua atividade.", "explicacao": "CTN, art. 127, I. A autoridade pode recusar o domicílio eleito que dificulte a fiscalização."}, {"id": 2000004020, "trilha": "fiscal", "materia": "trib", "assunto": "Lançamento", "tipo": "pergunta", "frente": "O que é o lançamento tributário pelo CTN?", "verso": "Procedimento administrativo, privativo da autoridade administrativa e vinculado, que verifica o fato gerador, determina a matéria tributável, calcula o tributo, identifica o sujeito passivo e propõe a penalidade.", "explicacao": "CTN, art. 142."}, {"id": 2000004021, "trilha": "fiscal", "materia": "trib", "assunto": "Lançamento", "tipo": "pergunta", "frente": "Qual lei rege o lançamento?", "verso": "A lei vigente na data do fato gerador, ainda que depois modificada ou revogada.", "explicacao": "CTN, art. 144. Normas que ampliam poderes de fiscalização aplicam-se a fatos anteriores (§ 1º)."}, {"id": 2000004022, "trilha": "fiscal", "materia": "trib", "assunto": "Lançamento", "tipo": "pergunta", "frente": "Em que casos o lançamento regularmente notificado pode ser alterado?", "verso": "Por impugnação do sujeito passivo, recurso de ofício ou iniciativa de ofício da autoridade, nos casos do art. 149.", "explicacao": "CTN, art. 145."}, {"id": 2000004023, "trilha": "fiscal", "materia": "trib", "assunto": "Lançamento", "tipo": "pergunta", "frente": "A mudança de critério jurídico pode alterar lançamento já feito?", "verso": "Não. O novo critério só vale para fatos geradores posteriores à sua introdução.", "explicacao": "CTN, art. 146."}, {"id": 2000004024, "trilha": "fiscal", "materia": "trib", "assunto": "Lançamento", "tipo": "pergunta", "frente": "Quando a autoridade pode arbitrar a base de cálculo?", "verso": "Quando as declarações ou documentos do sujeito passivo forem omissos ou não merecerem fé, assegurada a avaliação contraditória.", "explicacao": "CTN, art. 148."}, {"id": 2000004025, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Qual a ordem da imputação em pagamento quando há vários débitos?", "verso": "Primeiro os débitos por obrigação própria, depois os de responsabilidade; contribuições de melhoria, taxas e impostos; ordem crescente de prazos de prescrição; ordem decrescente de valores.", "explicacao": "CTN, art. 163."}, {"id": 2000004026, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Qual o vencimento do crédito tributário quando a lei não fixa prazo?", "verso": "30 dias depois da notificação do lançamento.", "explicacao": "CTN, art. 160."}, {"id": 2000004027, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Qual a taxa de juros de mora no CTN quando a lei não dispõe de outro modo?", "verso": "1% ao mês.", "explicacao": "CTN, art. 161, § 1º. Na União, aplica-se a Selic."}, {"id": 2000004028, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Quando cabe a consignação em pagamento do crédito tributário?", "verso": "Recusa de recebimento, subordinação do pagamento a exigência ilegal ou exigência do mesmo tributo por mais de um ente sobre o mesmo fato gerador.", "explicacao": "CTN, art. 164."}, {"id": 2000004029, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Qual o prazo para pedir restituição de tributo pago indevidamente?", "verso": "5 anos, contados da extinção do crédito tributário (em regra, do pagamento).", "explicacao": "CTN, art. 168, e LC 118/2005, art. 3º."}, {"id": 2000004030, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Quem pode pedir restituição de tributo indireto, como ICMS e IPI?", "verso": "Quem provar ter assumido o encargo financeiro ou estar autorizado por quem o suportou.", "explicacao": "CTN, art. 166, e Súmula 546 do STF."}, {"id": 2000004031, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Pode haver compensação com crédito discutido em juízo antes do trânsito em julgado?", "verso": "Não.", "explicacao": "CTN, art. 170-A."}, {"id": 2000004032, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "A dação em pagamento de bens imóveis extingue o crédito tributário?", "verso": "Sim, na forma e nas condições estabelecidas em lei.", "explicacao": "CTN, art. 156, XI, incluído pela LC 104/2001."}, {"id": 2000004033, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "O que é a transação tributária?", "verso": "Concessões mútuas entre Fisco e sujeito passivo para terminar litígio e extinguir o crédito, nos termos da lei.", "explicacao": "CTN, art. 171. Na União, Lei 13.988/2020."}, {"id": 2000004034, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Em que caso o prazo decadencial conta da decisão que anula o lançamento?", "verso": "Quando o lançamento anterior foi anulado por vício formal: conta-se da data em que a decisão se tornou definitiva.", "explicacao": "CTN, art. 173, II."}, {"id": 2000004035, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "pergunta", "frente": "Prazos de prescrição e decadência tributárias podem ser fixados por lei ordinária?", "verso": "Não. Exigem lei complementar.", "explicacao": "Súmula Vinculante 8 e CF, art. 146, III, b."}, {"id": 2000004036, "trilha": "fiscal", "materia": "trib", "assunto": "Exclusão do crédito", "tipo": "pergunta", "frente": "A isenção se estende às taxas e às contribuições de melhoria?", "verso": "Não, salvo disposição de lei em contrário. Também não alcança tributos instituídos depois de sua concessão.", "explicacao": "CTN, art. 177."}, {"id": 2000004037, "trilha": "fiscal", "materia": "trib", "assunto": "Exclusão do crédito", "tipo": "pergunta", "frente": "A anistia alcança atos qualificados como crime ou praticados com dolo, fraude ou simulação?", "verso": "Não.", "explicacao": "CTN, art. 180, I."}, {"id": 2000004038, "trilha": "fiscal", "materia": "trib", "assunto": "Exclusão do crédito", "tipo": "pergunta", "frente": "A anistia abrange quais infrações no tempo?", "verso": "Só as cometidas antes da vigência da lei que a concede.", "explicacao": "CTN, art. 180."}, {"id": 2000004039, "trilha": "fiscal", "materia": "trib", "assunto": "Garantias", "tipo": "pergunta", "frente": "O que é a indisponibilidade de bens do art. 185-A do CTN?", "verso": "Se o devedor citado não paga nem apresenta bens à penhora no prazo, o juiz determina a indisponibilidade de seus bens e direitos.", "explicacao": "CTN, art. 185-A."}, {"id": 2000004040, "trilha": "fiscal", "materia": "trib", "assunto": "Garantias", "tipo": "pergunta", "frente": "A cobrança judicial do crédito tributário se sujeita a concurso de credores ou habilitação em falência?", "verso": "Não.", "explicacao": "CTN, art. 187."}, {"id": 2000004041, "trilha": "fiscal", "materia": "trib", "assunto": "Garantias", "tipo": "pergunta", "frente": "Na falência, quais créditos preferem ao tributário?", "verso": "Créditos extraconcursais, importâncias passíveis de restituição, créditos trabalhistas até 150 salários mínimos por credor, de acidente de trabalho e com garantia real até o valor do bem.", "explicacao": "CTN, art. 186, parágrafo único, e Lei 11.101/2005, art. 83."}, {"id": 2000004042, "trilha": "fiscal", "materia": "trib", "assunto": "Administração tributária", "tipo": "pergunta", "frente": "As instituições financeiras são obrigadas a prestar informações ao Fisco?", "verso": "Sim, mediante intimação escrita, assim como tabeliães, corretores, leiloeiros, administradores de bens e outros.", "explicacao": "CTN, art. 197. O STF validou o acesso a dados bancários sem ordem judicial (LC 105/2001)."}, {"id": 2000004043, "trilha": "fiscal", "materia": "trib", "assunto": "Administração tributária", "tipo": "pergunta", "frente": "O que é o sigilo fiscal?", "verso": "Proibição de a Fazenda divulgar informações sobre a situação econômica ou financeira do contribuinte obtidas em razão do ofício.", "explicacao": "CTN, art. 198. Há exceções, como requisição judicial."}, {"id": 2000004044, "trilha": "fiscal", "materia": "trib", "assunto": "Administração tributária", "tipo": "pergunta", "frente": "Qual o prazo para a Fazenda expedir certidão negativa?", "verso": "10 dias da data do requerimento.", "explicacao": "CTN, art. 205, parágrafo único."}, {"id": 2000004045, "trilha": "fiscal", "materia": "trib", "assunto": "Administração tributária", "tipo": "pergunta", "frente": "Qual a presunção que goza a dívida regularmente inscrita?", "verso": "Presunção relativa de certeza e liquidez, com efeito de prova pré-constituída.", "explicacao": "CTN, art. 204."}, {"id": 2000004046, "trilha": "fiscal", "materia": "trib", "assunto": "Administração tributária", "tipo": "pergunta", "frente": "Até quando a Fazenda pode substituir a CDA na execução fiscal?", "verso": "Até a sentença de embargos, para corrigir erro material ou formal, vedada a modificação do sujeito passivo.", "explicacao": "Súmula 392 do STJ."}, {"id": 2000004047, "trilha": "fiscal", "materia": "trib", "assunto": "Súmulas", "tipo": "pergunta", "frente": "É constitucional exigir depósito prévio para admitir recurso administrativo?", "verso": "Não.", "explicacao": "Súmula Vinculante 21."}, {"id": 2000004048, "trilha": "fiscal", "materia": "trib", "assunto": "Súmulas", "tipo": "pergunta", "frente": "Quando se tipifica o crime material contra a ordem tributária?", "verso": "Só depois do lançamento definitivo do tributo.", "explicacao": "Súmula Vinculante 24."}, {"id": 2000004049, "trilha": "fiscal", "materia": "trib", "assunto": "Súmulas", "tipo": "pergunta", "frente": "Incide ISS sobre locação de bens móveis?", "verso": "Não. É inconstitucional.", "explicacao": "Súmula Vinculante 31."}, {"id": 2000004050, "trilha": "fiscal", "materia": "trib", "assunto": "Súmulas", "tipo": "pergunta", "frente": "A taxa pode usar elemento da base de cálculo de um imposto?", "verso": "Sim, desde que não haja identidade integral entre uma base e outra.", "explicacao": "Súmula Vinculante 29."}, {"id": 2000004051, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "Qual o fato gerador do imposto de renda pelo CTN?", "verso": "A aquisição da disponibilidade econômica ou jurídica de renda (produto do capital, do trabalho ou de ambos) e de proventos de qualquer natureza.", "explicacao": "CTN, art. 43."}, {"id": 2000004052, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "Quais os fatos geradores do IPI?", "verso": "O desembaraço aduaneiro do produto importado, a saída do produto do estabelecimento industrial e a arrematação de produto apreendido levado a leilão.", "explicacao": "CTN, art. 46."}, {"id": 2000004053, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "O IPI incide na exportação?", "verso": "Não. Há imunidade para produtos industrializados destinados ao exterior.", "explicacao": "CF, art. 153, § 3º, III."}, {"id": 2000004054, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "Quais as exceções do IOF aos princípios?", "verso": "Pode ter alíquotas alteradas pelo Executivo e não se sujeita às anterioridades de exercício e nonagesimal.", "explicacao": "CF, arts. 150, § 1º, e 153, § 1º."}, {"id": 2000004055, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "Como é tributado o ouro como ativo financeiro?", "verso": "Só pelo IOF, na operação de origem, com alíquota mínima de 1%.", "explicacao": "CF, art. 153, § 5º. 70% vão para o município de origem e 30% para o estado."}, {"id": 2000004056, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "O ITR pode ser fiscalizado e cobrado pelo município?", "verso": "Sim. O município que optar, na forma da lei, fica com 100% da arrecadação, desde que não reduza o imposto nem conceda renúncia.", "explicacao": "CF, art. 153, § 4º, III, e art. 158, II."}, {"id": 2000004057, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos estaduais", "tipo": "pergunta", "frente": "Incide ICMS no deslocamento de mercadoria entre estabelecimentos do mesmo titular?", "verso": "Não.", "explicacao": "Súmula 166 do STJ e ADC 49 do STF."}, {"id": 2000004058, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos estaduais", "tipo": "pergunta", "frente": "O ICMS incide na importação feita por pessoa física?", "verso": "Sim, qualquer que seja a finalidade, mesmo sem habitualidade.", "explicacao": "CF, art. 155, § 2º, IX, a."}, {"id": 2000004059, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos estaduais", "tipo": "pergunta", "frente": "O que é o diferencial de alíquota (DIFAL) do ICMS?", "verso": "Nas vendas a consumidor final de outro estado, o estado de destino fica com a diferença entre sua alíquota interna e a alíquota interestadual.", "explicacao": "CF, art. 155, § 2º, VII, com redação da EC 87/2015."}, {"id": 2000004060, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos estaduais", "tipo": "pergunta", "frente": "Quem fixa as alíquotas máximas do ITCMD?", "verso": "O Senado Federal.", "explicacao": "CF, art. 155, § 1º, IV. Após a EC 132/2023, o ITCMD deve ser progressivo conforme o valor."}, {"id": 2000004061, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos estaduais", "tipo": "pergunta", "frente": "Onde é devido o ITCMD sobre bens imóveis?", "verso": "No estado da situação do bem.", "explicacao": "CF, art. 155, § 1º, I. Sobre bens móveis, títulos e créditos, no estado de domicílio do falecido ou do doador (redação da EC 132/2023)."}, {"id": 2000004062, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos estaduais", "tipo": "pergunta", "frente": "Após a EC 132/2023, o IPVA passou a incidir sobre quais veículos?", "verso": "Também sobre veículos aquáticos e aéreos, com exceções, e pode ter alíquotas diferenciadas pelo impacto ambiental.", "explicacao": "CF, art. 155, § 6º."}, {"id": 2000004063, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos municipais", "tipo": "pergunta", "frente": "Qual o fato gerador do IPTU pelo CTN?", "verso": "A propriedade, o domínio útil ou a posse de bem imóvel por natureza ou acessão física, localizado na zona urbana do município.", "explicacao": "CTN, art. 32."}, {"id": 2000004064, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos municipais", "tipo": "pergunta", "frente": "Qual a alíquota mínima e máxima do ISS?", "verso": "Mínima de 2% e máxima de 5%.", "explicacao": "ADCT, art. 88, e LC 116/2003, art. 8º."}, {"id": 2000004065, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos municipais", "tipo": "pergunta", "frente": "Onde é devido o ISS, em regra?", "verso": "No local do estabelecimento prestador ou, na falta, no domicílio do prestador, salvo as exceções da LC 116/2003 (ex.: construção civil, no local da obra).", "explicacao": "LC 116/2003, art. 3º."}, {"id": 2000004066, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos municipais", "tipo": "pergunta", "frente": "Incide ITBI na integralização de capital social com imóvel?", "verso": "Não, salvo se a atividade preponderante da empresa for compra e venda, locação ou arrendamento de imóveis.", "explicacao": "CF, art. 156, § 2º, I."}, {"id": 2000004067, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos municipais", "tipo": "pergunta", "frente": "Quando o ITBI é devido, segundo o STF?", "verso": "Com o registro da transferência da propriedade no cartório de imóveis, e não com a assinatura do compromisso de compra e venda.", "explicacao": "Tema 1.124 do STF."}, {"id": 2000004068, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos municipais", "tipo": "pergunta", "frente": "O que é o IPTU progressivo no tempo?", "verso": "Aumento da alíquota por até 5 anos para o imóvel urbano não edificado, subutilizado ou não utilizado, para forçar o cumprimento da função social.", "explicacao": "CF, art. 182, § 4º, II, e Estatuto da Cidade, art. 7º."}, {"id": 2000004069, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "Quais tributos a reforma tributária (EC 132/2023) vai extinguir?", "verso": "PIS, Cofins, IPI (reduzido a zero, salvo produtos da Zona Franca), ICMS e ISS.", "explicacao": "Serão substituídos por CBS, IBS e Imposto Seletivo."}, {"id": 2000004070, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "Quem administra o IBS?", "verso": "O Comitê Gestor do IBS, formado por estados, Distrito Federal e municípios.", "explicacao": "CF, art. 156-B, e LC 214/2025."}, {"id": 2000004071, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "Qual o princípio de cobrança do IBS e da CBS nas operações entre estados?", "verso": "O princípio do destino: o tributo vai para o local de consumo.", "explicacao": "Acaba a guerra fiscal baseada na origem."}, {"id": 2000004072, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "O que é a não cumulatividade ampla do IBS e da CBS?", "verso": "Direito de crédito sobre todos os bens e serviços adquiridos, salvo os de uso e consumo pessoal definidos em lei.", "explicacao": "CF, arts. 156-A, § 1º, VIII, e 195, § 16."}, {"id": 2000004073, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "O que é o cashback da reforma tributária?", "verso": "Devolução de parte do IBS e da CBS a famílias de baixa renda, para reduzir a regressividade.", "explicacao": "CF, art. 156-A, § 5º, VIII, e LC 214/2025."}, {"id": 2000004074, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "O que é a Cesta Básica Nacional de Alimentos na reforma?", "verso": "Lista de alimentos com alíquota zero de IBS e CBS.", "explicacao": "EC 132/2023, art. 8º, e LC 214/2025."}, {"id": 2000004075, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "Quando o ICMS e o ISS deixam de existir completamente?", "verso": "Em 2033, após a transição gradual de 2029 a 2032.", "explicacao": "EC 132/2023. A CBS substitui PIS e Cofins a partir de 2027."}, {"id": 2000004076, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "O que é o split payment?", "verso": "Recolhimento automático do IBS e da CBS no momento do pagamento da operação, separando o tributo do valor pago ao fornecedor.", "explicacao": "Previsto na LC 214/2025."}, {"id": 2000004077, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "pergunta", "frente": "Sobre o que incide o Imposto Seletivo?", "verso": "Produção, extração, comercialização ou importação de bens e serviços prejudiciais à saúde ou ao meio ambiente.", "explicacao": "CF, art. 153, VIII. Ex.: cigarros, bebidas alcoólicas e veículos poluentes."}, {"id": 2000004078, "trilha": "fiscal", "materia": "trib", "assunto": "Regimes", "tipo": "pergunta", "frente": "Qual o limite de receita bruta anual da empresa de pequeno porte no Simples Nacional?", "verso": "R$ 4,8 milhões.", "explicacao": "LC 123/2006, art. 3º, II. Microempresa: até R$ 360 mil."}, {"id": 2000004079, "trilha": "fiscal", "materia": "trib", "assunto": "Regimes", "tipo": "pergunta", "frente": "Qual o limite de receita bruta anual do MEI?", "verso": "R$ 81 mil.", "explicacao": "LC 123/2006, art. 18-A."}, {"id": 2000004080, "trilha": "fiscal", "materia": "trib", "assunto": "Regimes", "tipo": "pergunta", "frente": "Até que receita a empresa pode optar pelo lucro presumido?", "verso": "Até R$ 78 milhões no ano-calendário anterior.", "explicacao": "Lei 9.718/1998, art. 13."}, {"id": 2000004081, "trilha": "fiscal", "materia": "trib", "assunto": "Regimes", "tipo": "pergunta", "frente": "Quais empresas são obrigadas ao lucro real?", "verso": "As com receita acima de R$ 78 milhões, instituições financeiras, empresas com lucros do exterior, entre outras.", "explicacao": "Lei 9.718/1998, art. 14."}, {"id": 2000004082, "trilha": "fiscal", "materia": "trib", "assunto": "Crimes tributários", "tipo": "pares", "frente": "Qual a diferença entre os crimes do art. 1º e do art. 2º da Lei 8.137/1990?", "verso": "Art. 1º: crimes materiais, exigem a supressão ou redução do tributo. Art. 2º: crimes formais, como deixar de recolher tributo descontado ou cobrado de terceiros.", "explicacao": "Lei 8.137/1990."}, {"id": 2000004083, "trilha": "fiscal", "materia": "trib", "assunto": "Crimes tributários", "tipo": "pergunta", "frente": "O pagamento integral do tributo extingue a punibilidade do crime tributário?", "verso": "Sim, a qualquer tempo, inclusive após o recebimento da denúncia, segundo a jurisprudência.", "explicacao": "Lei 10.684/2003, art. 9º, § 2º. O parcelamento suspende a pretensão punitiva."}, {"id": 2000004084, "trilha": "fiscal", "materia": "trib", "assunto": "Crimes tributários", "tipo": "pergunta", "frente": "Deixar de recolher ICMS declarado, de forma contumaz e com dolo de apropriação, é crime?", "verso": "Sim. O STF entende que configura o crime do art. 2º, II, da Lei 8.137/1990.", "explicacao": "RHC 163.334 (2019)."}, {"id": 2000004085, "trilha": "fiscal", "materia": "trib", "assunto": "Processo tributário", "tipo": "pergunta", "frente": "Qual o prazo para pagar ou garantir a execução fiscal após a citação?", "verso": "5 dias.", "explicacao": "Lei 6.830/1980, art. 8º."}, {"id": 2000004086, "trilha": "fiscal", "materia": "trib", "assunto": "Processo tributário", "tipo": "pergunta", "frente": "Os embargos à execução fiscal exigem garantia do juízo?", "verso": "Sim.", "explicacao": "Lei 6.830/1980, art. 16, § 1º."}, {"id": 2000004087, "trilha": "fiscal", "materia": "trib", "assunto": "Processo tributário", "tipo": "pergunta", "frente": "O que é a exceção de pré-executividade?", "verso": "Defesa sem garantia do juízo, para matérias conhecíveis de ofício que não exijam produção de provas.", "explicacao": "Súmula 393 do STJ."}, {"id": 2000004088, "trilha": "fiscal", "materia": "trib", "assunto": "Processo tributário", "tipo": "pergunta", "frente": "Qual ação o contribuinte usa para obter declaração de que não deve o tributo, antes do lançamento?", "verso": "Ação declaratória de inexistência de relação jurídico-tributária.", "explicacao": "Depois do lançamento, cabe ação anulatória."}, {"id": 2000004089, "trilha": "fiscal", "materia": "trib", "assunto": "Princípios", "tipo": "certo_errado", "frente": "Certo ou errado? A taxa e a contribuição de melhoria se submetem ao princípio da capacidade contributiva da mesma forma que os impostos.", "verso": "Errado. A Constituição prevê a capacidade contributiva para os impostos, \"sempre que possível\".", "explicacao": "CF, art. 145, § 1º. O STF admite sua aplicação a outras espécies em certos casos."}, {"id": 2000004090, "trilha": "fiscal", "materia": "trib", "assunto": "Princípios", "tipo": "pergunta", "frente": "Quais tributos são exceção apenas à anterioridade nonagesimal (90 dias)?", "verso": "O imposto de renda e a fixação da base de cálculo do IPTU e do IPVA: respeitam a anterioridade de exercício, mas não a noventena.", "explicacao": "CF, art. 150, § 1º. II, IE, IOF, empréstimo compulsório de guerra e IEG são exceção às duas."}, {"id": 2000004091, "trilha": "fiscal", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "Templos de qualquer culto têm imunidade de quais tributos?", "verso": "De impostos sobre patrimônio, renda e serviços relacionados às suas finalidades essenciais.", "explicacao": "CF, art. 150, VI, b. A EC 132/2023 estendeu às entidades religiosas e organizações assistenciais e beneficentes."}, {"id": 2000004092, "trilha": "fiscal", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "A imunidade dos partidos políticos e sindicatos alcança quais entidades sindicais?", "verso": "As dos trabalhadores. Sindicatos patronais não têm essa imunidade.", "explicacao": "CF, art. 150, VI, c."}, {"id": 2000004093, "trilha": "fiscal", "materia": "trib", "assunto": "Imunidades", "tipo": "pergunta", "frente": "Há imunidade de impostos para fonogramas e videofonogramas musicais?", "verso": "Sim, os produzidos no Brasil com obras musicais de autores brasileiros ou interpretadas por artistas brasileiros, salvo a etapa de replicação industrial de mídias ópticas.", "explicacao": "CF, art. 150, VI, e (EC 75/2013)."}, {"id": 2000004094, "trilha": "fiscal", "materia": "cont", "assunto": "Imobilizado", "tipo": "pergunta", "frente": "Quais gastos compõem o custo do ativo imobilizado, segundo o CPC 27?", "verso": "Preço de aquisição (com impostos não recuperáveis, menos descontos), custos para colocar o ativo em condição de uso (frete, instalação, montagem) e estimativa de custos de desmontagem e remoção.", "explicacao": "CPC 27, item 16."}, {"id": 2000004095, "trilha": "fiscal", "materia": "cont", "assunto": "Imobilizado", "tipo": "pergunta", "frente": "Gastos de manutenção diária do imobilizado são ativados?", "verso": "Não. São reconhecidos como despesa no resultado.", "explicacao": "CPC 27, item 12. Só gastos que aumentam benefícios futuros são ativados."}, {"id": 2000004096, "trilha": "fiscal", "materia": "cont", "assunto": "Imobilizado", "tipo": "pergunta", "frente": "A vida útil e o valor residual do imobilizado devem ser revisados?", "verso": "Sim, pelo menos ao final de cada exercício. A mudança é tratada como mudança de estimativa (prospectiva).", "explicacao": "CPC 27, item 51."}, {"id": 2000004097, "trilha": "fiscal", "materia": "cont", "assunto": "Imobilizado", "tipo": "pergunta", "frente": "Quando começa a depreciação de um ativo?", "verso": "Quando ele está disponível para uso, no local e em condição de funcionamento.", "explicacao": "CPC 27, item 55."}, {"id": 2000004098, "trilha": "fiscal", "materia": "cont", "assunto": "Imobilizado", "tipo": "pergunta", "frente": "Qual a depreciação anual pelo método da soma dos dígitos de um bem de R$ 15.000, vida útil de 5 anos e sem valor residual, no 1º ano?", "verso": "R$ 5.000.", "explicacao": "Soma dos dígitos: 1+2+3+4+5 = 15. 1º ano: 5/15 × 15.000."}, {"id": 2000004099, "trilha": "fiscal", "materia": "cont", "assunto": "Imobilizado", "tipo": "pergunta", "frente": "O que é o método das unidades produzidas?", "verso": "Depreciação proporcional ao uso: (unidades produzidas no período ÷ total estimado) × valor depreciável.", "explicacao": "Adequado quando o desgaste depende da produção."}, {"id": 2000004100, "trilha": "fiscal", "materia": "cont", "assunto": "Intangível", "tipo": "pares", "frente": "Como o CPC 04 trata gastos com pesquisa e com desenvolvimento?", "verso": "Pesquisa: sempre despesa. Desenvolvimento: pode ser ativado se demonstrada a viabilidade técnica, a intenção e a capacidade de concluir e usar ou vender, entre outros requisitos.", "explicacao": "CPC 04, itens 54 a 57."}, {"id": 2000004101, "trilha": "fiscal", "materia": "cont", "assunto": "Intangível", "tipo": "pergunta", "frente": "Marcas, títulos de publicações e listas de clientes gerados internamente podem ser ativados?", "verso": "Não.", "explicacao": "CPC 04, item 63."}, {"id": 2000004102, "trilha": "fiscal", "materia": "cont", "assunto": "Intangível", "tipo": "pergunta", "frente": "O goodwill gerado internamente pode ser reconhecido como ativo?", "verso": "Não.", "explicacao": "CPC 04, item 48. Só o goodwill adquirido em combinação de negócios."}, {"id": 2000004103, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "O que é valor realizável líquido (VRL)?", "verso": "Preço de venda estimado menos os custos estimados para concluir o produto e para vendê-lo.", "explicacao": "CPC 16. Se o custo for maior que o VRL, reduz-se o estoque ao VRL."}, {"id": 2000004104, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Pelo método PEPS, quais custos ficam no estoque final?", "verso": "Os das compras mais recentes.", "explicacao": "Os primeiros que entram são os primeiros que saem para o CMV."}, {"id": 2000004105, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Gastos com armazenamento e despesas de venda entram no custo do estoque?", "verso": "Não, salvo armazenamento necessário ao processo produtivo. Despesas de venda e administrativas são despesas do período.", "explicacao": "CPC 16, item 16."}, {"id": 2000004106, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Inventário periódico x permanente: qual a diferença?", "verso": "Periódico: o estoque é apurado por contagem física no fim do período, e o CMV por diferença. Permanente: cada entrada e saída é registrada, e o CMV é apurado a cada venda.", "explicacao": "Métodos de controle de estoques."}, {"id": 2000004107, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Uma empresa tem EI de R$ 20.000, compras de R$ 80.000, devoluções de compras de R$ 5.000 e EF de R$ 15.000. Qual o CMV?", "verso": "R$ 80.000.", "explicacao": "CMV = 20.000 + (80.000 − 5.000) − 15.000."}, {"id": 2000004108, "trilha": "fiscal", "materia": "cont", "assunto": "Operações com mercadorias", "tipo": "pergunta", "frente": "Como se contabiliza a venda de mercadorias a prazo com ICMS?", "verso": "D Clientes / C Receita de vendas; D ICMS sobre vendas (dedução) / C ICMS a recolher.", "explicacao": "Pelo método de inventário permanente, também D CMV / C Mercadorias."}, {"id": 2000004109, "trilha": "fiscal", "materia": "cont", "assunto": "Operações com mercadorias", "tipo": "pergunta", "frente": "Como a devolução de vendas aparece na DRE?", "verso": "Como dedução da receita bruta.", "explicacao": "Junto com abatimentos, descontos incondicionais e tributos sobre vendas."}, {"id": 2000004110, "trilha": "fiscal", "materia": "cont", "assunto": "Operações com mercadorias", "tipo": "pergunta", "frente": "Uma empresa teve receita bruta de R$ 200.000, ICMS de R$ 36.000 e devoluções de R$ 4.000. Qual a receita líquida?", "verso": "R$ 160.000.", "explicacao": "200.000 − 36.000 − 4.000."}, {"id": 2000004111, "trilha": "fiscal", "materia": "cont", "assunto": "Operações com mercadorias", "tipo": "pergunta", "frente": "Descontos financeiros obtidos aparecem onde na DRE?", "verso": "Como receitas financeiras.", "explicacao": "Os concedidos são despesas financeiras."}, {"id": 2000004112, "trilha": "fiscal", "materia": "cont", "assunto": "Passivo", "tipo": "pergunta", "frente": "Como se contabiliza a provisão de férias dos empregados mês a mês?", "verso": "D Despesa de férias / C Férias a pagar (passivo), incluindo os encargos.", "explicacao": "Regime de competência."}, {"id": 2000004113, "trilha": "fiscal", "materia": "cont", "assunto": "Passivo", "tipo": "pergunta", "frente": "O que são \"Duplicatas descontadas\" e onde ficam?", "verso": "Títulos de clientes antecipados no banco; a empresa continua responsável. Ficam no passivo circulante (empréstimo), pelo CPC.", "explicacao": "Antes eram redutoras do ativo."}, {"id": 2000004114, "trilha": "fiscal", "materia": "cont", "assunto": "Passivo", "tipo": "pergunta", "frente": "O que são adiantamentos de clientes?", "verso": "Valores recebidos antes da entrega do bem ou serviço, registrados no passivo (passivo de contrato).", "explicacao": "Viram receita quando a obrigação é cumprida (CPC 47)."}, {"id": 2000004115, "trilha": "fiscal", "materia": "cont", "assunto": "Tributos sobre o lucro", "tipo": "pergunta", "frente": "O que gera um passivo fiscal diferido?", "verso": "Diferenças temporárias tributáveis: o resultado contábil reconhece hoje uma receita que só será tributada no futuro.", "explicacao": "CPC 32."}, {"id": 2000004116, "trilha": "fiscal", "materia": "cont", "assunto": "Tributos sobre o lucro", "tipo": "pares", "frente": "Qual a diferença entre diferença temporária e permanente para fins de IR?", "verso": "Temporária: será tributada ou deduzida no futuro (gera tributo diferido). Permanente: nunca será tributada ou deduzida (não gera diferido).", "explicacao": "CPC 32."}, {"id": 2000004117, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "Quando a constituição da reserva legal é facultativa?", "verso": "Quando a reserva legal somada às reservas de capital exceder 30% do capital social.", "explicacao": "Lei 6.404/1976, art. 193, § 1º."}, {"id": 2000004118, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "Qual o limite das reservas de lucros, exceto contingências, incentivos fiscais e lucros a realizar?", "verso": "Não podem ultrapassar o capital social. O excesso deve ser usado para aumentar capital ou distribuir dividendos.", "explicacao": "Lei 6.404/1976, art. 199."}, {"id": 2000004119, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "O que é a reserva para contingências?", "verso": "Parcela do lucro destinada a compensar provável diminuição do lucro em exercício futuro por perda que possa ser estimada.", "explicacao": "Lei 6.404/1976, art. 195."}, {"id": 2000004120, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "O que é a reserva de incentivos fiscais?", "verso": "Parcela do lucro decorrente de doações ou subvenções governamentais para investimentos, que pode ser excluída da base do dividendo obrigatório.", "explicacao": "Lei 6.404/1976, art. 195-A."}, {"id": 2000004121, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "O que são juros sobre capital próprio?", "verso": "Remuneração aos sócios calculada sobre o PL, limitada à TJLP, dedutível do IR e da CSLL da empresa.", "explicacao": "Lei 9.249/1995, art. 9º. Podem ser imputados ao dividendo mínimo."}, {"id": 2000004122, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "Uma empresa teve lucro líquido de R$ 100.000. Quanto vai para a reserva legal?", "verso": "R$ 5.000.", "explicacao": "5% do lucro líquido, até atingir 20% do capital social."}, {"id": 2000004123, "trilha": "fiscal", "materia": "cont", "assunto": "Investimentos", "tipo": "pergunta", "frente": "A partir de que participação se presume influência significativa?", "verso": "20% ou mais do capital votante da investida, sem controlá-la.", "explicacao": "Lei 6.404/1976, art. 243, § 5º, e CPC 18."}, {"id": 2000004124, "trilha": "fiscal", "materia": "cont", "assunto": "Investimentos", "tipo": "pergunta", "frente": "Como se registra o lucro da coligada pela equivalência patrimonial?", "verso": "D Investimentos / C Resultado de equivalência patrimonial (receita), pela participação proporcional.", "explicacao": "Os dividendos recebidos reduzem o investimento."}, {"id": 2000004125, "trilha": "fiscal", "materia": "cont", "assunto": "Investimentos", "tipo": "pergunta", "frente": "O que é propriedade para investimento (CPC 28)?", "verso": "Imóvel mantido para auferir aluguel ou valorização, e não para uso próprio ou venda no curso normal.", "explicacao": "Pode ser avaliado pelo custo ou pelo valor justo."}, {"id": 2000004126, "trilha": "fiscal", "materia": "cont", "assunto": "Investimentos", "tipo": "pergunta", "frente": "Como se avaliam os ativos biológicos pelo CPC 29?", "verso": "Pelo valor justo menos a despesa de venda, com as variações reconhecidas no resultado.", "explicacao": "Ex.: gado e plantações. Plantas portadoras seguem o CPC 27."}, {"id": 2000004127, "trilha": "fiscal", "materia": "cont", "assunto": "Instrumentos financeiros", "tipo": "pergunta", "frente": "Quais as categorias de mensuração de ativos financeiros no CPC 48?", "verso": "Custo amortizado, valor justo por meio de outros resultados abrangentes (VJORA) e valor justo por meio do resultado (VJR).", "explicacao": "Depende do modelo de negócios e das características do fluxo de caixa."}, {"id": 2000004128, "trilha": "fiscal", "materia": "cont", "assunto": "Valor justo", "tipo": "pergunta", "frente": "Quais os níveis da hierarquia do valor justo?", "verso": "Nível 1: preços cotados em mercado ativo para itens idênticos. Nível 2: outros dados observáveis. Nível 3: dados não observáveis.", "explicacao": "CPC 46."}, {"id": 2000004129, "trilha": "fiscal", "materia": "cont", "assunto": "Receita", "tipo": "pergunta", "frente": "Quais as cinco etapas do reconhecimento de receita no CPC 47?", "verso": "Identificar o contrato; identificar as obrigações de desempenho; determinar o preço; alocar o preço às obrigações; reconhecer a receita quando cada obrigação for satisfeita.", "explicacao": "CPC 47."}, {"id": 2000004130, "trilha": "fiscal", "materia": "cont", "assunto": "Receita", "tipo": "pergunta", "frente": "Quando a receita é reconhecida ao longo do tempo?", "verso": "Quando o cliente recebe e consome os benefícios à medida que a empresa executa, ou quando a empresa cria um ativo que o cliente controla, entre outros critérios.", "explicacao": "CPC 47, item 35. Ex.: serviços contínuos."}, {"id": 2000004131, "trilha": "fiscal", "materia": "cont", "assunto": "Eventos subsequentes", "tipo": "pares", "frente": "Qual a diferença entre evento subsequente que origina ajuste e que não origina ajuste?", "verso": "Origina ajuste: evidencia condição que já existia na data do balanço (ex.: sentença sobre processo antigo). Não origina: condição surgida depois (ex.: incêndio), só divulgada.", "explicacao": "CPC 24."}, {"id": 2000004132, "trilha": "fiscal", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "Na DFC, onde podem ser classificados os juros pagos?", "verso": "Como atividade operacional ou de financiamento, de forma consistente. O CPC 03 incentiva classificar como operacional.", "explicacao": "CPC 03 (R2), item 33A."}, {"id": 2000004133, "trilha": "fiscal", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "Na DFC pelo método indireto, como a depreciação é tratada?", "verso": "É somada de volta ao lucro líquido, porque é despesa que não afeta o caixa.", "explicacao": "CPC 03."}, {"id": 2000004134, "trilha": "fiscal", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "Na DFC pelo método indireto, como entra o aumento de clientes a receber?", "verso": "É subtraído do lucro, porque parte das vendas não virou caixa.", "explicacao": "Aumento de ativo operacional reduz o caixa; aumento de passivo operacional aumenta."}, {"id": 2000004135, "trilha": "fiscal", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "O que é a Demonstração do Resultado Abrangente (DRA)?", "verso": "Demonstração que parte do lucro líquido e acrescenta os outros resultados abrangentes, como ajustes de avaliação patrimonial.", "explicacao": "CPC 26."}, {"id": 2000004136, "trilha": "fiscal", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "O que deve conter a DMPL?", "verso": "As mutações de todas as contas do PL no período: capital, reservas, ajustes de avaliação, lucros ou prejuízos, dividendos e ações em tesouraria.", "explicacao": "CPC 26. Substitui a DLPA."}, {"id": 2000004137, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Como se calcula o giro do estoque?", "verso": "CMV ÷ estoque médio.", "explicacao": "O prazo médio de estocagem é 360 ÷ giro."}, {"id": 2000004138, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Como se calcula o prazo médio de pagamento a fornecedores?", "verso": "(Fornecedores médios ÷ compras) × 360.", "explicacao": "Ciclo financeiro = PME + PMR − PMP."}, {"id": 2000004139, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Uma empresa tem PME de 60 dias, PMR de 45 dias e PMP de 30 dias. Qual o ciclo financeiro?", "verso": "75 dias.", "explicacao": "60 + 45 − 30. O ciclo operacional é 105 dias (PME + PMR)."}, {"id": 2000004140, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Como se calcula a margem líquida?", "verso": "Lucro líquido ÷ receita líquida.", "explicacao": "Indica quanto sobra de lucro para cada real vendido."}, {"id": 2000004141, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Como se calcula o ROA (retorno sobre o ativo)?", "verso": "Lucro líquido (ou operacional) ÷ ativo total.", "explicacao": "Mede a eficiência no uso dos ativos."}, {"id": 2000004142, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "O que mede a composição do endividamento?", "verso": "A proporção das dívidas de curto prazo no total de dívidas: passivo circulante ÷ capital de terceiros.", "explicacao": "Quanto maior, mais pressão no curto prazo."}, {"id": 2000004143, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "O que mede a imobilização do patrimônio líquido?", "verso": "Quanto do PL está aplicado no ativo não circulante (investimentos, imobilizado e intangível).", "explicacao": "(Inv. + Imob. + Intangível) ÷ PL."}, {"id": 2000004144, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "O que é a departamentalização de custos?", "verso": "Divisão da fábrica em departamentos (produtivos e de serviço) para ratear os custos indiretos de forma mais precisa.", "explicacao": "Os custos dos departamentos de serviço são rateados aos produtivos."}, {"id": 2000004145, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "O que é o custo-padrão?", "verso": "Custo predeterminado do que deveria ser gasto, usado para controle por comparação com o custo real.", "explicacao": "As diferenças são as variações."}, {"id": 2000004146, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "O que é a margem de segurança?", "verso": "O quanto as vendas podem cair até atingir o ponto de equilíbrio: (vendas atuais − vendas no PE) ÷ vendas atuais.", "explicacao": "Mede a folga operacional."}, {"id": 2000004147, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "Uma empresa vende a R$ 50, com custo variável de R$ 30 e custos fixos de R$ 40.000. Qual o ponto de equilíbrio contábil?", "verso": "2.000 unidades.", "explicacao": "40.000 ÷ (50 − 30)."}, {"id": 2000004148, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "Qual a diferença entre ponto de equilíbrio contábil, econômico e financeiro?", "verso": "Contábil: lucro zero. Econômico: cobre também o custo de oportunidade (lucro desejado). Financeiro: exclui despesas que não afetam o caixa, como a depreciação.", "explicacao": "PEF < PEC < PEE, em regra."}, {"id": 2000004149, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pares", "frente": "Qual a diferença entre coprodutos e subprodutos?", "verso": "Coprodutos: produtos principais de um mesmo processo, com valor relevante. Subprodutos: itens secundários de valor pequeno, com mercado próprio.", "explicacao": "Sucatas não têm mercado regular."}, {"id": 2000004150, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pares", "frente": "Como se tratam as perdas normais e anormais na produção?", "verso": "Normais (inerentes ao processo) integram o custo dos produtos. Anormais (involuntárias e eventuais) são despesas do período.", "explicacao": "Princípio do custeio."}, {"id": 2000004151, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "O que é equivalente de produção?", "verso": "Conversão de unidades em processo em unidades acabadas equivalentes, para apurar o custo unitário.", "explicacao": "Ex.: 100 unidades 50% prontas equivalem a 50 acabadas."}, {"id": 2000004152, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "O que é custo de oportunidade na contabilidade gerencial?", "verso": "O benefício que se deixa de ganhar ao escolher uma alternativa em vez de outra.", "explicacao": "Não é registrado contabilmente."}, {"id": 2000004153, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "Quais as classes do Plano de Contas Aplicado ao Setor Público (PCASP)?", "verso": "1 Ativo, 2 Passivo e PL, 3 Variações patrimoniais diminutivas, 4 Variações patrimoniais aumentativas, 5 e 6 Controles orçamentários, 7 e 8 Controles devedores e credores.", "explicacao": "MCASP."}, {"id": 2000004154, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pares", "frente": "Qual a diferença entre VPA e VPD?", "verso": "VPA (variação patrimonial aumentativa) aumenta o patrimônio líquido, como receita. VPD (diminutiva) o reduz, como despesa.", "explicacao": "Registradas pelo regime de competência."}, {"id": 2000004155, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "O que mostra a Demonstração das Variações Patrimoniais (DVP)?", "verso": "As alterações do patrimônio resultantes ou independentes da execução orçamentária, e o resultado patrimonial do período.", "explicacao": "Lei 4.320/1964, art. 104, e MCASP."}, {"id": 2000004156, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pares", "frente": "Qual a diferença entre ativo financeiro e ativo permanente na Lei 4.320?", "verso": "Financeiro: créditos e valores realizáveis independentemente de autorização orçamentária, e numerário. Permanente: bens e valores cuja movimentação depende de autorização legislativa.", "explicacao": "Lei 4.320/1964, art. 105."}, {"id": 2000004157, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "Como se apura o superávit financeiro do balanço patrimonial?", "verso": "Ativo financeiro menos passivo financeiro, conjugando os créditos adicionais e operações de crédito vinculadas.", "explicacao": "Lei 4.320/1964, art. 43, § 2º. É fonte para abrir créditos adicionais."}, {"id": 2000004158, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "O que é o excesso de arrecadação?", "verso": "Saldo positivo entre a arrecadação prevista e a realizada, considerando a tendência do exercício.", "explicacao": "Lei 4.320/1964, art. 43, § 3º. Fonte de créditos adicionais."}, {"id": 2000004159, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "Os bens do setor público são depreciados?", "verso": "Sim. O MCASP e as NBC TSP exigem depreciação, amortização e exaustão dos ativos.", "explicacao": "Regime de competência no patrimonial."}, {"id": 2000004160, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "O que são as NBC TSP?", "verso": "Normas Brasileiras de Contabilidade Aplicadas ao Setor Público, convergentes às normas internacionais (IPSAS).", "explicacao": "Editadas pelo CFC."}, {"id": 2000004161, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pares", "frente": "Qual a diferença entre receita originária e derivada?", "verso": "Originária: vem da exploração do patrimônio do próprio Estado (aluguéis, preços públicos). Derivada: vem do patrimônio do particular por coerção (tributos).", "explicacao": "Classificação doutrinária."}, {"id": 2000004162, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "Quais as origens da receita corrente?", "verso": "Impostos, taxas e contribuições de melhoria; contribuições; patrimonial; agropecuária; industrial; serviços; transferências correntes; e outras receitas correntes.", "explicacao": "Lei 4.320/1964, art. 11, e MCASP."}, {"id": 2000004163, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "Quais as origens da receita de capital?", "verso": "Operações de crédito; alienação de bens; amortização de empréstimos concedidos; transferências de capital; e outras receitas de capital.", "explicacao": "Lei 4.320/1964, art. 11, § 2º."}, {"id": 2000004164, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "Como se estrutura o código de natureza da receita?", "verso": "Categoria econômica, origem, espécie, desdobramentos para identificar peculiaridades e tipo.", "explicacao": "MCASP. Ex.: 1.1.1.x para impostos."}, {"id": 2000004165, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "O que é a previsão da receita?", "verso": "A estimativa da arrecadação feita para o orçamento, considerando a legislação, a variação de preços e o crescimento econômico.", "explicacao": "LRF, art. 12."}, {"id": 2000004166, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "A LRF obriga o ente a instituir e arrecadar todos os seus tributos?", "verso": "Sim. É requisito de responsabilidade na gestão fiscal; quem não arrecada impostos fica impedido de receber transferências voluntárias.", "explicacao": "LRF, art. 11."}, {"id": 2000004167, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é a modalidade de aplicação da despesa?", "verso": "Indica se os recursos serão aplicados diretamente pelo órgão ou transferidos a outros entes ou entidades.", "explicacao": "Ex.: 90 = aplicação direta."}, {"id": 2000004168, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "Quais as etapas de planejamento da despesa?", "verso": "Fixação, descentralização dos créditos, programação orçamentária e financeira e processo de licitação e contratação.", "explicacao": "Depois vêm empenho, liquidação e pagamento."}, {"id": 2000004169, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é a nota de empenho?", "verso": "Documento que materializa o empenho, indicando credor, valor e dedução da dotação.", "explicacao": "Lei 4.320/1964, art. 61. Pode ser dispensada em casos previstos."}, {"id": 2000004170, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é a ordem bancária na União?", "verso": "O documento usado para efetuar o pagamento da despesa pela conta única.", "explicacao": "Sucede a ordem de pagamento."}, {"id": 2000004171, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é o suprimento de fundos?", "verso": "Adiantamento a servidor para despesas que não possam seguir o processo normal, como despesas eventuais, de pequeno vulto ou sigilosas.", "explicacao": "Lei 4.320/1964, art. 68. Exige empenho prévio e prestação de contas."}, {"id": 2000004172, "trilha": "fiscal", "materia": "afo", "assunto": "Dívida", "tipo": "pares", "frente": "Qual a diferença entre dívida flutuante e dívida fundada?", "verso": "Flutuante: de curto prazo, independe de autorização orçamentária (restos a pagar, depósitos, ARO). Fundada: compromissos de prazo superior a 12 meses, para atender desequilíbrio orçamentário ou financiar obras.", "explicacao": "Lei 4.320/1964, arts. 92 e 98, e LRF, art. 29."}, {"id": 2000004173, "trilha": "fiscal", "materia": "afo", "assunto": "Dívida", "tipo": "pergunta", "frente": "Quais os limites da dívida consolidada líquida fixados pelo Senado?", "verso": "Estados e DF: 2 vezes a RCL. Municípios: 1,2 vez a RCL.", "explicacao": "Resolução do Senado 40/2001."}, {"id": 2000004174, "trilha": "fiscal", "materia": "afo", "assunto": "Dívida", "tipo": "pergunta", "frente": "Qual o prazo para reconduzir a dívida ao limite quando ultrapassado?", "verso": "3 quadrimestres, reduzindo pelo menos 25% do excesso no primeiro.", "explicacao": "LRF, art. 31."}, {"id": 2000004175, "trilha": "fiscal", "materia": "afo", "assunto": "Dívida", "tipo": "pergunta", "frente": "O que acontece com o ente enquanto a dívida estiver acima do limite?", "verso": "Fica proibido de contratar operações de crédito (salvo refinanciamento) e deve obter resultado primário para reduzir a dívida, entre outras restrições.", "explicacao": "LRF, art. 31, § 1º."}, {"id": 2000004176, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é a limitação de empenho da LRF e quando ocorre?", "verso": "Bloqueio de despesas quando, ao fim de um bimestre, a receita puder não comportar o cumprimento das metas de resultado.", "explicacao": "LRF, art. 9º. Prazo de 30 dias."}, {"id": 2000004177, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que se exige para criar ou aumentar despesa por ação governamental?", "verso": "Estimativa do impacto orçamentário-financeiro no exercício e nos dois seguintes e declaração do ordenador de que há adequação com a LOA e compatibilidade com o PPA e a LDO.", "explicacao": "LRF, art. 16."}, {"id": 2000004178, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é o Anexo de Metas Fiscais da LDO?", "verso": "Anexo com metas anuais de receitas, despesas, resultados nominal e primário e dívida para o exercício e os dois seguintes.", "explicacao": "LRF, art. 4º, § 1º."}, {"id": 2000004179, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é o Anexo de Riscos Fiscais?", "verso": "Anexo da LDO que avalia passivos contingentes e outros riscos capazes de afetar as contas públicas, com as providências se ocorrerem.", "explicacao": "LRF, art. 4º, § 3º."}, {"id": 2000004180, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "A receita da alienação de bens pode financiar despesas correntes?", "verso": "Não, salvo se destinada por lei aos regimes de previdência social.", "explicacao": "LRF, art. 44."}, {"id": 2000004181, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que a LRF exige antes de incluir novos projetos na LOA?", "verso": "Que estejam adequadamente atendidos os projetos em andamento e contempladas as despesas de conservação do patrimônio.", "explicacao": "LRF, art. 45."}, {"id": 2000004182, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "A LRF permite que o ente faça operação de crédito com a instituição financeira que ele controla?", "verso": "Não, como beneficiário do empréstimo.", "explicacao": "LRF, art. 36. Podem ser aplicadas reservas em títulos da dívida pública."}, {"id": 2000004183, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Quais condições a LRF exige para transferências voluntárias?", "verso": "Existência de dotação, vedação para pessoal, comprovação de regularidade (tributos, prestação de contas, limites de pessoal e dívida) e contrapartida prevista na LDO.", "explicacao": "LRF, art. 25."}, {"id": 2000004184, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que a LRF exige para destinar recursos públicos a pessoas físicas ou ao setor privado?", "verso": "Autorização por lei específica, atender às condições da LDO e estar prevista no orçamento.", "explicacao": "LRF, art. 26."}, {"id": 2000004185, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Em que prazo devem ser publicados o RREO e o RGF?", "verso": "RREO: até 30 dias após o encerramento de cada bimestre. RGF: até 30 dias após o fim do quadrimestre.", "explicacao": "LRF, arts. 52 e 55, § 2º. Municípios com menos de 50 mil habitantes podem optar pelo RGF semestral."}, {"id": 2000004186, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Quem assina o Relatório de Gestão Fiscal?", "verso": "Os titulares dos Poderes e órgãos, o responsável pela administração financeira e o responsável pelo controle interno.", "explicacao": "LRF, art. 54."}, {"id": 2000004187, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que a Lei Complementar 131/2009 acrescentou à LRF?", "verso": "A transparência em tempo real: divulgação na internet, em tempo real, de informações detalhadas sobre a execução orçamentária e financeira.", "explicacao": "LRF, art. 48-A."}, {"id": 2000004188, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Quais vedações se aplicam ao Poder que excedeu 95% do limite de pessoal?", "verso": "Conceder vantagem ou reajuste (salvo revisão geral e decisões judiciais), criar cargo, alterar carreira com aumento de despesa, prover cargos (salvo reposição em educação, saúde e segurança) e pagar hora extra (salvo exceções).", "explicacao": "LRF, art. 22, parágrafo único."}, {"id": 2000004189, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Que despesas entram na despesa com pessoal da LRF, além dos salários?", "verso": "Encargos sociais, contribuições previdenciárias, inativos e pensionistas, e terceirização de mão de obra que substitui servidores.", "explicacao": "LRF, art. 18."}, {"id": 2000004190, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Quais medidas a Constituição prevê para reduzir a despesa com pessoal acima do limite?", "verso": "Primeiro, reduzir em pelo menos 20% as despesas com cargos em comissão e funções de confiança e exonerar servidores não estáveis. Se não bastar, exonerar estáveis.", "explicacao": "CF, art. 169, §§ 3º e 4º."}, {"id": 2000004191, "trilha": "fiscal", "materia": "afo", "assunto": "Orçamento na CF", "tipo": "pergunta", "frente": "Qual o percentual das emendas de bancada estadual de execução obrigatória?", "verso": "Até 1% da receita corrente líquida do exercício anterior.", "explicacao": "CF, art. 166, § 12."}, {"id": 2000004192, "trilha": "fiscal", "materia": "afo", "assunto": "Orçamento na CF", "tipo": "pergunta", "frente": "Até que dia de cada mês são entregues os duodécimos aos Poderes Legislativo e Judiciário, ao MP e à Defensoria?", "verso": "Até o dia 20.", "explicacao": "CF, art. 168."}, {"id": 2000004193, "trilha": "fiscal", "materia": "afo", "assunto": "Orçamento na CF", "tipo": "pergunta", "frente": "Que matéria exige lei complementar no direito financeiro?", "verso": "Dispor sobre exercício financeiro, vigência, prazos, elaboração e organização do PPA, LDO e LOA, e normas de gestão financeira e patrimonial.", "explicacao": "CF, art. 165, § 9º."}, {"id": 2000004194, "trilha": "fiscal", "materia": "afo", "assunto": "Orçamento na CF", "tipo": "pergunta", "frente": "Que vedações o art. 167 da CF traz sobre créditos?", "verso": "Proíbe iniciar programas não incluídos na LOA, realizar despesas que excedam os créditos, abrir crédito suplementar ou especial sem autorização legislativa e indicação de recursos, entre outras.", "explicacao": "CF, art. 167."}, {"id": 2000004195, "trilha": "fiscal", "materia": "afo", "assunto": "Orçamento na CF", "tipo": "pergunta", "frente": "O que é o orçamento de investimento das estatais?", "verso": "Parte da LOA com os investimentos das empresas em que a União detém a maioria do capital votante.", "explicacao": "CF, art. 165, § 5º, II."}, {"id": 2000004196, "trilha": "fiscal", "materia": "afo", "assunto": "Orçamento na CF", "tipo": "pergunta", "frente": "O que é o orçamento da seguridade social?", "verso": "Parte da LOA que abrange entidades e órgãos da saúde, previdência e assistência social.", "explicacao": "CF, art. 165, § 5º, III."}, {"id": 2000004197, "trilha": "fiscal", "materia": "afo", "assunto": "Arcabouço fiscal", "tipo": "pergunta", "frente": "Qual o limite de crescimento real da despesa primária no arcabouço fiscal (LC 200/2023)?", "verso": "Entre 0,6% e 2,5% ao ano acima da inflação, correspondendo a 70% do crescimento real da receita (50% se a meta de resultado primário não for cumprida).", "explicacao": "LC 200/2023, art. 5º."}, {"id": 2000004198, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da publicidade orçamentária?", "verso": "O orçamento e sua execução devem ser divulgados por meios oficiais, permitindo o controle pela sociedade.", "explicacao": "CF, art. 37 e art. 165, § 3º."}, {"id": 2000004199, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da programação?", "verso": "O orçamento deve expressar objetivos, metas e programas de trabalho, ligados ao planejamento.", "explicacao": "Característica do orçamento-programa."}, {"id": 2000004200, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da clareza orçamentária?", "verso": "O orçamento deve ser expresso de forma clara, ordenada e compreensível para todos.", "explicacao": "Princípio doutrinário."}, {"id": 2000004201, "trilha": "fiscal", "materia": "afo", "assunto": "Classificações", "tipo": "pergunta", "frente": "O que responde a classificação institucional da despesa?", "verso": "Quem faz o gasto: órgão e unidade orçamentária.", "explicacao": "A funcional responde \"em que área\"; a programática, \"para quê\"; a natureza, \"o quê\"."}, {"id": 2000004202, "trilha": "fiscal", "materia": "afo", "assunto": "Classificações", "tipo": "pergunta", "frente": "A classificação funcional pode combinar função de uma área com subfunção de outra?", "verso": "Sim. As subfunções podem ser combinadas com funções diferentes daquelas a que estão vinculadas (matricialidade).", "explicacao": "Portaria MOG 42/1999."}, {"id": 2000004203, "trilha": "fiscal", "materia": "afo", "assunto": "Restos a pagar", "tipo": "pergunta", "frente": "Os restos a pagar não processados podem ser cancelados?", "verso": "Sim. Quando não liquidados até o prazo, são cancelados, observadas as regras do decreto de execução.", "explicacao": "Decreto 93.872/1986, art. 68, na União."}, {"id": 2000004204, "trilha": "fiscal", "materia": "afo", "assunto": "Restos a pagar", "tipo": "pergunta", "frente": "A inscrição em restos a pagar não processados exige o quê no último ano de mandato?", "verso": "Disponibilidade de caixa para as obrigações contraídas nos dois últimos quadrimestres.", "explicacao": "LRF, art. 42."}, {"id": 2000004205, "trilha": "fiscal", "materia": "afo", "assunto": "Controle", "tipo": "pergunta", "frente": "O que é o controle interno integrado dos Poderes, segundo a CF?", "verso": "Sistema que avalia o cumprimento das metas do PPA, a execução dos programas e dos orçamentos, a legalidade e os resultados da gestão, e apoia o controle externo.", "explicacao": "CF, art. 74."}, {"id": 2000004206, "trilha": "fiscal", "materia": "afo", "assunto": "Controle", "tipo": "pergunta", "frente": "Qual o prazo para o Presidente prestar contas ao Congresso?", "verso": "Dentro de 60 dias após a abertura da sessão legislativa.", "explicacao": "CF, art. 84, XXIV. O TCU emite parecer prévio em 60 dias (art. 71, I)."}, {"id": 2000004207, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que o auditor deve fazer antes de aceitar um novo cliente?", "verso": "Avaliar a integridade da administração, sua competência e independência, e se consegue cumprir as exigências éticas e o prazo.", "explicacao": "NBC TA 220 e NBC PA 01 (controle de qualidade)."}, {"id": 2000004208, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é o entendimento da entidade e do seu ambiente?", "verso": "Conhecer o setor, a regulação, a natureza da entidade, as políticas contábeis, os objetivos e o controle interno, para identificar riscos de distorção.", "explicacao": "NBC TA 315."}, {"id": 2000004209, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é risco significativo em auditoria?", "verso": "Risco de distorção relevante que, no julgamento do auditor, exige consideração especial, como transações incomuns ou estimativas complexas.", "explicacao": "NBC TA 315."}, {"id": 2000004210, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "Quais referenciais costumam ser usados para a materialidade de uma empresa com lucro estável?", "verso": "Um percentual do lucro antes dos impostos, em geral em torno de 5%.", "explicacao": "NBC TA 320. Em entidades sem fins lucrativos, usa-se receita ou despesa total."}, {"id": 2000004211, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que é reexecução?", "verso": "O auditor executa de forma independente procedimentos ou controles que originalmente fazem parte do controle interno da entidade.", "explicacao": "NBC TA 500. Ex.: refazer uma conciliação bancária."}, {"id": 2000004212, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que é observação como procedimento de auditoria?", "verso": "Acompanhar um processo ou procedimento executado por outros, como a contagem de estoques pelos empregados.", "explicacao": "Limitada ao momento observado."}, {"id": 2000004213, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Qual a afirmação testada no corte (cut-off) de vendas?", "verso": "Corte: as transações foram registradas no período contábil correto.", "explicacao": "Ex.: vendas de dezembro registradas em janeiro."}, {"id": 2000004214, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Qual afirmação é testada ao verificar se o estoque está registrado pelo menor entre custo e VRL?", "verso": "Avaliação (valorização).", "explicacao": "NBC TA 315."}, {"id": 2000004215, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que fazer quando o cliente não responde à confirmação positiva?", "verso": "Aplicar procedimentos alternativos, como examinar recebimentos posteriores ou documentos de embarque.", "explicacao": "NBC TA 505."}, {"id": 2000004216, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que fazer se a administração não permite enviar uma confirmação?", "verso": "Avaliar se a recusa é razoável, obter evidências alternativas e considerar o efeito sobre o risco de fraude e sobre a opinião.", "explicacao": "NBC TA 505, item 8."}, {"id": 2000004217, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que são estimativas contábeis e por que são áreas de risco?", "verso": "Valores aproximados na ausência de medida precisa, como provisões e valor justo. Envolvem julgamento e podem ser manipuladas.", "explicacao": "NBC TA 540."}, {"id": 2000004218, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Quando o auditor usa o trabalho de um especialista?", "verso": "Quando precisa de conhecimento fora da contabilidade e da auditoria, como avaliação de imóveis, cálculo atuarial ou engenharia.", "explicacao": "NBC TA 620. O auditor continua responsável pela opinião."}, {"id": 2000004219, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que é a revisão analítica no fim da auditoria?", "verso": "Procedimentos analíticos para verificar se as demonstrações, no conjunto, são consistentes com o entendimento do auditor.", "explicacao": "NBC TA 520."}, {"id": 2000004220, "trilha": "fiscal", "materia": "aud", "assunto": "Amostragem", "tipo": "pergunta", "frente": "O que é estratificação na amostragem de auditoria?", "verso": "Dividir a população em subgrupos com características semelhantes, como faixas de valor, para tornar a amostra mais eficiente.", "explicacao": "NBC TA 530."}, {"id": 2000004221, "trilha": "fiscal", "materia": "aud", "assunto": "Amostragem", "tipo": "pergunta", "frente": "O que é a amostragem por unidade monetária (PPS)?", "verso": "Cada real da população tem a mesma chance de ser selecionado, o que favorece itens de maior valor.", "explicacao": "Usada em testes de superavaliação."}, {"id": 2000004222, "trilha": "fiscal", "materia": "aud", "assunto": "Amostragem", "tipo": "pergunta", "frente": "O que é desvio tolerável?", "verso": "A taxa máxima de desvio nos controles que o auditor aceita para confiar no controle.", "explicacao": "NBC TA 530, para testes de controle."}, {"id": 2000004223, "trilha": "fiscal", "materia": "aud", "assunto": "Fraude", "tipo": "pares", "frente": "Qual a diferença entre informação financeira fraudulenta e apropriação indébita de ativos?", "verso": "Informação fraudulenta: manipular as demonstrações para enganar os usuários. Apropriação indébita: furtar ativos da entidade.", "explicacao": "NBC TA 240."}, {"id": 2000004224, "trilha": "fiscal", "materia": "aud", "assunto": "Fraude", "tipo": "pergunta", "frente": "O que o auditor faz se identificar fraude envolvendo a administração?", "verso": "Comunica aos responsáveis pela governança e avalia as implicações para a auditoria, inclusive para a confiabilidade das representações.", "explicacao": "NBC TA 240."}, {"id": 2000004225, "trilha": "fiscal", "materia": "aud", "assunto": "Fraude", "tipo": "pergunta", "frente": "O que diz a NBC TA 250 sobre leis e regulamentos?", "verso": "O auditor deve obter evidência sobre o cumprimento das leis com efeito direto nas demonstrações e estar atento a não conformidades.", "explicacao": "Ex.: leis tributárias e trabalhistas."}, {"id": 2000004226, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "Qual a estrutura básica do relatório do auditor independente?", "verso": "Título, destinatário, opinião, base para opinião, continuidade (se aplicável), PAA (se aplicável), outras informações, responsabilidades da administração e do auditor, assinatura, data e local.", "explicacao": "NBC TA 700. A opinião vem em primeiro lugar."}, {"id": 2000004227, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "O que são as \"outras informações\" no relatório do auditor?", "verso": "Informações do relatório anual da entidade além das demonstrações, como o relatório da administração, que o auditor deve ler para identificar inconsistências relevantes.", "explicacao": "NBC TA 720."}, {"id": 2000004228, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "A data do relatório do auditor pode ser anterior à aprovação das demonstrações pela administração?", "verso": "Não. Deve ser posterior à obtenção de evidência suficiente, inclusive de que as demonstrações foram preparadas e aprovadas.", "explicacao": "NBC TA 700, item 49."}, {"id": 2000004229, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "Que opinião se emite se a administração impõe limitação de alcance com efeitos relevantes e generalizados?", "verso": "Abstenção de opinião, podendo o auditor renunciar ao trabalho, se permitido.", "explicacao": "NBC TA 705, item 13."}, {"id": 2000004230, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "O que é o parágrafo de outros assuntos?", "verso": "Parágrafo sobre assunto não apresentado nas demonstrações, mas relevante para o entendimento da auditoria, como o fato de outro auditor ter examinado o ano anterior.", "explicacao": "NBC TA 706."}, {"id": 2000004231, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "O que é o ambiente de controle no COSO?", "verso": "A base de todos os componentes: integridade, valores éticos, estrutura de governança e atitude da administração (\"tom do topo\").", "explicacao": "COSO I."}, {"id": 2000004232, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "Quantos princípios o COSO 2013 associa aos componentes do controle interno?", "verso": "17 princípios.", "explicacao": "Distribuídos pelos 5 componentes."}, {"id": 2000004233, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "O que é o COSO ERM?", "verso": "Estrutura de gerenciamento de riscos corporativos, que integra riscos à estratégia e ao desempenho.", "explicacao": "Atualizado em 2017."}, {"id": 2000004234, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "O que são controles gerais de TI?", "verso": "Controles sobre o ambiente de tecnologia, como acesso aos sistemas, mudanças de programas e operações de TI.", "explicacao": "Diferentes dos controles de aplicativo."}, {"id": 2000004235, "trilha": "fiscal", "materia": "aud", "assunto": "Ética", "tipo": "pergunta", "frente": "O que é a ameaça de autorrevisão?", "verso": "Quando o auditor avalia trabalho feito por ele mesmo ou por sua firma, como revisar registros contábeis que ajudou a preparar.", "explicacao": "NBC PA 400."}, {"id": 2000004236, "trilha": "fiscal", "materia": "aud", "assunto": "Ética", "tipo": "pergunta", "frente": "O que é a ameaça de familiaridade?", "verso": "Quando, pelo relacionamento longo ou próximo, o auditor fica muito solidário aos interesses do cliente.", "explicacao": "Mitigada pelo rodízio."}, {"id": 2000004237, "trilha": "fiscal", "materia": "aud", "assunto": "Ética", "tipo": "pergunta", "frente": "O auditor pode ter interesse financeiro no cliente de auditoria?", "verso": "Não. Interesse financeiro direto ou indireto relevante compromete a independência.", "explicacao": "NBC PA 400 (ameaça de interesse próprio)."}, {"id": 2000004238, "trilha": "fiscal", "materia": "aud", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que são as NBASP?", "verso": "As Normas Brasileiras de Auditoria do Setor Público, baseadas nas normas internacionais (ISSAI) da Intosai.", "explicacao": "Editadas pelo Instituto Rui Barbosa."}, {"id": 2000004239, "trilha": "fiscal", "materia": "aud", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é a auditoria operacional nos tribunais de contas?", "verso": "Exame independente da economicidade, eficiência, eficácia e efetividade de programas, projetos e organizações públicas.", "explicacao": "ISSAI 300."}, {"id": 2000004240, "trilha": "fiscal", "materia": "aud", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é a matriz de achados na auditoria governamental?", "verso": "Instrumento que organiza cada achado com situação encontrada, critério, evidências, causas, efeitos e recomendações.", "explicacao": "Usada pelo TCU."}, {"id": 2000004241, "trilha": "fiscal", "materia": "aud", "assunto": "Setor público", "tipo": "pergunta", "frente": "Quais os elementos de um achado de auditoria?", "verso": "Critério (o que deveria ser), condição (o que é), causa e efeito.", "explicacao": "Base das recomendações."}, {"id": 2000004242, "trilha": "fiscal", "materia": "aud", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é a tomada de contas especial?", "verso": "Processo para apurar responsabilidade por dano ao erário, identificar os responsáveis e quantificar o dano, buscando o ressarcimento.", "explicacao": "Lei 8.443/1992 (Lei Orgânica do TCU), art. 8º."}, {"id": 2000004243, "trilha": "fiscal", "materia": "aud", "assunto": "Setor público", "tipo": "pergunta", "frente": "As decisões do TCU que imputam débito têm que natureza?", "verso": "Título executivo.", "explicacao": "CF, art. 71, § 3º."}, {"id": 2000004244, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria interna", "tipo": "pergunta", "frente": "Quais são as normas globais de auditoria interna atuais?", "verso": "As Normas Globais de Auditoria Interna do IIA, publicadas em 2024, que substituíram o antigo IPPF.", "explicacao": "Estruturadas em domínios, princípios e padrões."}, {"id": 2000004245, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria interna", "tipo": "pergunta", "frente": "A auditoria interna pode assumir responsabilidades operacionais da gestão?", "verso": "Não, pois isso prejudica sua objetividade e independência.", "explicacao": "Normas do IIA."}, {"id": 2000004246, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é o excedente do consumidor?", "verso": "A diferença entre o que o consumidor estaria disposto a pagar e o que efetivamente paga.", "explicacao": "Área abaixo da curva de demanda e acima do preço."}, {"id": 2000004247, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é o excedente do produtor?", "verso": "A diferença entre o preço recebido e o mínimo que o produtor aceitaria (seu custo marginal).", "explicacao": "Área acima da curva de oferta e abaixo do preço."}, {"id": 2000004248, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é o peso morto de um tributo?", "verso": "A perda de bem-estar total causada pelo tributo, que nenhum agente aproveita, porque reduz a quantidade transacionada.", "explicacao": "Maior quanto mais elásticas a oferta e a demanda."}, {"id": 2000004249, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é a elasticidade-renda da demanda?", "verso": "A variação percentual da quantidade demandada dividida pela variação percentual da renda.", "explicacao": "Positiva: bem normal. Negativa: bem inferior. Maior que 1: bem de luxo."}, {"id": 2000004250, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é a elasticidade cruzada da demanda?", "verso": "A variação percentual da demanda de um bem dividida pela variação percentual do preço de outro.", "explicacao": "Positiva: substitutos. Negativa: complementares."}, {"id": 2000004251, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "Se o preço sobe 10% e a quantidade demandada cai 20%, qual a elasticidade-preço?", "verso": "−2 (demanda elástica).", "explicacao": "−20% ÷ 10%. Em módulo maior que 1."}, {"id": 2000004252, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é a curva de indiferença?", "verso": "Conjunto de cestas de bens que dão a mesma satisfação (utilidade) ao consumidor.", "explicacao": "Tangente à restrição orçamentária no ótimo."}, {"id": 2000004253, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é a taxa marginal de substituição?", "verso": "Quanto de um bem o consumidor aceita trocar por uma unidade a mais de outro, mantendo a mesma utilidade.", "explicacao": "Inclinação da curva de indiferença."}, {"id": 2000004254, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pares", "frente": "Qual a diferença entre efeito substituição e efeito renda?", "verso": "Substituição: o consumidor troca o bem que ficou mais caro por outro relativamente mais barato. Renda: a variação de preço muda o poder de compra.", "explicacao": "Bem de Giffen: o efeito renda supera o substituição."}, {"id": 2000004255, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é o custo marginal?", "verso": "O custo de produzir uma unidade a mais.", "explicacao": "Na concorrência perfeita, a firma produz onde preço = custo marginal."}, {"id": 2000004256, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "Quando a empresa em concorrência perfeita deve parar de produzir no curto prazo?", "verso": "Quando o preço fica abaixo do custo variável médio mínimo.", "explicacao": "Ponto de fechamento."}, {"id": 2000004257, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é monopólio natural?", "verso": "Mercado em que uma única empresa abastece a demanda a custo menor que várias, por fortes economias de escala.", "explicacao": "Ex.: saneamento, transmissão de energia. Costuma ser regulado."}, {"id": 2000004258, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é discriminação de preços?", "verso": "Cobrar preços diferentes de consumidores diferentes pelo mesmo produto, conforme a disposição a pagar.", "explicacao": "Ex.: meia-entrada, passagens aéreas."}, {"id": 2000004259, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é o dilema dos prisioneiros?", "verso": "Situação em que cada jogador, agindo racionalmente em seu interesse, chega a um resultado pior para ambos do que se cooperassem.", "explicacao": "Teoria dos jogos."}, {"id": 2000004260, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é assimetria de informação?", "verso": "Quando uma parte da transação sabe mais que a outra.", "explicacao": "Gera seleção adversa (antes) e risco moral (depois)."}, {"id": 2000004261, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é o problema do agente-principal?", "verso": "Conflito quando o agente (ex.: gestor) age em interesse próprio e não no do principal (ex.: acionista), que não consegue monitorá-lo bem.", "explicacao": "Ligado ao risco moral."}, {"id": 2000004262, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é o deflator implícito do PIB?", "verso": "PIB nominal ÷ PIB real × 100. Mede a variação de preços de todos os bens e serviços produzidos.", "explicacao": "Índice de preços mais amplo."}, {"id": 2000004263, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "Se o PIB nominal cresceu 10% e a inflação foi de 6%, qual o crescimento real aproximado?", "verso": "Cerca de 3,8%.", "explicacao": "(1,10 ÷ 1,06) − 1 ≈ 0,0377. A aproximação simples daria 4%."}, {"id": 2000004264, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é o hiato do produto?", "verso": "A diferença entre o PIB efetivo e o PIB potencial.", "explicacao": "Hiato negativo: economia ociosa, pressão inflacionária menor."}, {"id": 2000004265, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é a taxa natural de desemprego?", "verso": "A taxa de desemprego compatível com inflação estável, formada pelo desemprego friccional e estrutural.", "explicacao": "Também chamada de NAIRU."}, {"id": 2000004266, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é a armadilha da liquidez?", "verso": "Situação de juros muito baixos em que a política monetária perde eficácia, porque as pessoas retêm moeda.", "explicacao": "Conceito keynesiano."}, {"id": 2000004267, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que diz a equivalência ricardiana?", "verso": "Que financiar gastos com dívida em vez de impostos não altera o consumo, porque as pessoas antecipam impostos futuros e poupam.", "explicacao": "Pressupõe agentes racionais e sem restrição de crédito."}, {"id": 2000004268, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que diz a teoria quantitativa da moeda?", "verso": "M × V = P × Y: com velocidade e produto constantes, aumentar a moeda eleva os preços na mesma proporção.", "explicacao": "Base do monetarismo."}, {"id": 2000004269, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é senhoriagem?", "verso": "Receita que o governo obtém com a emissão de moeda.", "explicacao": "Pode gerar imposto inflacionário."}, {"id": 2000004270, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é o modelo IS-LM?", "verso": "Modelo de equilíbrio entre o mercado de bens (curva IS) e o mercado monetário (curva LM), que determina juros e renda.", "explicacao": "Política fiscal desloca a IS; monetária, a LM."}, {"id": 2000004271, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "No modelo Mundell-Fleming com câmbio flutuante e mobilidade de capital, qual política é eficaz?", "verso": "A monetária. A fiscal é anulada pela valorização cambial.", "explicacao": "Com câmbio fixo, ocorre o inverso."}, {"id": 2000004272, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é o compulsório bancário?", "verso": "Parcela dos depósitos que os bancos devem manter no Banco Central. Aumentá-lo reduz a oferta de crédito e de moeda.", "explicacao": "Instrumento de política monetária."}, {"id": 2000004273, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que são operações de mercado aberto (open market)?", "verso": "Compra e venda de títulos públicos pelo Banco Central para controlar a liquidez e manter a Selic na meta.", "explicacao": "Comprar títulos injeta moeda; vender recolhe."}, {"id": 2000004274, "trilha": "fiscal", "materia": "eco", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é a necessidade de financiamento do setor público (NFSP)?", "verso": "O resultado fiscal do setor público consolidado, que mostra quanto ele precisa se financiar.", "explicacao": "Conceito usado para medir o déficit."}, {"id": 2000004275, "trilha": "fiscal", "materia": "eco", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é dívida líquida do setor público (DLSP)?", "verso": "A dívida bruta menos os ativos financeiros do setor público, como reservas internacionais.", "explicacao": "Medida pelo Banco Central."}, {"id": 2000004276, "trilha": "fiscal", "materia": "eco", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é um tributo neutro?", "verso": "Tributo que não altera as decisões econômicas dos agentes (preços relativos).", "explicacao": "Exemplo teórico: imposto lump-sum (fixo)."}, {"id": 2000004277, "trilha": "fiscal", "materia": "eco", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é o princípio do benefício na tributação?", "verso": "Cada um paga de acordo com o benefício que recebe dos serviços públicos.", "explicacao": "Diferente do princípio da capacidade de pagamento."}, {"id": 2000004278, "trilha": "fiscal", "materia": "eco", "assunto": "Setor público", "tipo": "pergunta", "frente": "O que é equidade horizontal e vertical na tributação?", "verso": "Horizontal: quem está em situação igual paga igual. Vertical: quem tem mais capacidade paga mais.", "explicacao": "Base da progressividade."}, {"id": 2000004279, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "O que são as transações correntes no balanço de pagamentos?", "verso": "Balança comercial, serviços, renda primária (juros, lucros, salários) e renda secundária (transferências).", "explicacao": "Déficit em transações correntes precisa de financiamento externo."}, {"id": 2000004280, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "Onde se registra o investimento estrangeiro direto no balanço de pagamentos?", "verso": "Na conta financeira.", "explicacao": "Junto com investimentos em carteira e derivativos."}, {"id": 2000004281, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "O que é a paridade do poder de compra (PPC)?", "verso": "A ideia de que o câmbio deveria igualar o poder de compra das moedas, de modo que uma cesta custe o mesmo nos dois países.", "explicacao": "Ex.: Índice Big Mac."}, {"id": 2000004282, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "O que é câmbio real?", "verso": "Câmbio nominal ajustado pela diferença de preços entre os países; mede a competitividade.", "explicacao": "Real alta (depreciação real) favorece exportações."}, {"id": 2000004283, "trilha": "fiscal", "materia": "eco", "assunto": "Mercado financeiro", "tipo": "pergunta", "frente": "O que faz o Conselho Monetário Nacional?", "verso": "Formula a política da moeda e do crédito e define a meta de inflação.", "explicacao": "É o órgão normativo máximo do Sistema Financeiro Nacional."}, {"id": 2000004284, "trilha": "fiscal", "materia": "eco", "assunto": "Mercado financeiro", "tipo": "pergunta", "frente": "O que é o Copom?", "verso": "O Comitê de Política Monetária do Banco Central, que define a meta da taxa Selic.", "explicacao": "Reúne-se a cada 45 dias, em média."}, {"id": 2000004285, "trilha": "fiscal", "materia": "eco", "assunto": "Finanças", "tipo": "pergunta", "frente": "Qual a taxa anual equivalente a 2% ao mês em juros compostos?", "verso": "Cerca de 26,8%.", "explicacao": "(1,02)¹² − 1 ≈ 0,268."}, {"id": 2000004286, "trilha": "fiscal", "materia": "eco", "assunto": "Finanças", "tipo": "pergunta", "frente": "No sistema SAC, como se comportam as prestações?", "verso": "São decrescentes, porque a amortização é constante e os juros caem ao longo do tempo.", "explicacao": "No Price, as prestações são constantes."}, {"id": 2000004287, "trilha": "fiscal", "materia": "eco", "assunto": "Finanças", "tipo": "pergunta", "frente": "Como interpretar um VPL negativo?", "verso": "O projeto não remunera a taxa mínima de atratividade e deve ser rejeitado.", "explicacao": "VPL positivo: aceitar."}, {"id": 2000004288, "trilha": "fiscal", "materia": "eco", "assunto": "Finanças", "tipo": "pergunta", "frente": "O que é payback?", "verso": "O tempo necessário para recuperar o investimento inicial com os fluxos de caixa.", "explicacao": "Não considera os fluxos depois da recuperação."}, {"id": 2000004289, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "O que é a Duimp?", "verso": "Declaração Única de Importação, no Portal Único de Comércio Exterior, que substitui gradualmente a DI e a DSI.", "explicacao": "Programa Portal Único Siscomex."}, {"id": 2000004290, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "Qual o documento de exportação no Portal Único?", "verso": "A DU-E (Declaração Única de Exportação).", "explicacao": "Substituiu o RE, a DE e a DSE."}, {"id": 2000004291, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "O que é a conferência aduaneira?", "verso": "Procedimento para identificar o importador, verificar a mercadoria e a correção das informações quanto à natureza, classificação, quantidade e valor.", "explicacao": "Regulamento Aduaneiro, art. 564."}, {"id": 2000004292, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "O despacho de importação pode ser feito sem a mercadoria no país?", "verso": "Sim, em hipóteses previstas, como o despacho antecipado (antes da chegada da carga).", "explicacao": "IN SRF 680/2006, art. 17, e normas da Duimp."}, {"id": 2000004293, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "Quem pode representar o importador no despacho?", "verso": "O próprio importador (dirigente ou empregado credenciado) ou um despachante aduaneiro.", "explicacao": "Decreto-Lei 2.472/1988 e Regulamento Aduaneiro, art. 809."}, {"id": 2000004294, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "O que é o licenciamento de importação?", "verso": "Autorização prévia exigida para certas mercadorias, por órgãos anuentes como Anvisa, Mapa, Ibama e Exército.", "explicacao": "Pode ser automático ou não automático."}, {"id": 2000004295, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "O que é o conhecimento de carga?", "verso": "Documento do transportador que comprova o recebimento da mercadoria e a obrigação de entregá-la; serve como título de propriedade.", "explicacao": "Ex.: BL (marítimo) e AWB (aéreo)."}, {"id": 2000004296, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "O que é a fatura comercial (commercial invoice)?", "verso": "Documento do exportador estrangeiro com a descrição, quantidade, preço e condições da venda.", "explicacao": "Base para o valor aduaneiro."}, {"id": 2000004297, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "pergunta", "frente": "O que é o certificado de origem?", "verso": "Documento que comprova o país de origem da mercadoria, necessário para obter preferências tarifárias em acordos como o Mercosul.", "explicacao": "Regras de origem."}, {"id": 2000004298, "trilha": "fiscal", "materia": "adua", "assunto": "Valoração", "tipo": "pergunta", "frente": "Comissões de venda pagas pelo comprador integram o valor aduaneiro?", "verso": "Sim, quando suportadas pelo comprador e não incluídas no preço, exceto comissões de compra.", "explicacao": "Acordo de Valoração, art. 8."}, {"id": 2000004299, "trilha": "fiscal", "materia": "adua", "assunto": "Valoração", "tipo": "pergunta", "frente": "Royalties pagos como condição de venda integram o valor aduaneiro?", "verso": "Sim, quando relacionados à mercadoria e pagos como condição de venda.", "explicacao": "Acordo de Valoração, art. 8, 1, c."}, {"id": 2000004300, "trilha": "fiscal", "materia": "adua", "assunto": "Valoração", "tipo": "pergunta", "frente": "A vinculação entre comprador e vendedor impede o uso do valor de transação?", "verso": "Não por si só. O valor é aceito se a vinculação não influenciou o preço.", "explicacao": "Acordo de Valoração, art. 1, 2."}, {"id": 2000004301, "trilha": "fiscal", "materia": "adua", "assunto": "Classificação", "tipo": "pergunta", "frente": "Quantos dígitos tem o código NCM?", "verso": "8 dígitos: os 6 primeiros são do Sistema Harmonizado e os 2 últimos são do Mercosul.", "explicacao": "Nomenclatura Comum do Mercosul."}, {"id": 2000004302, "trilha": "fiscal", "materia": "adua", "assunto": "Classificação", "tipo": "pergunta", "frente": "O que são as Regras Gerais de Interpretação (RGI) do Sistema Harmonizado?", "verso": "Regras que orientam a classificação fiscal das mercadorias. A RGI 1 diz que vale o texto das posições e das notas de seção e capítulo.", "explicacao": "Os títulos das seções têm valor apenas indicativo."}, {"id": 2000004303, "trilha": "fiscal", "materia": "adua", "assunto": "Classificação", "tipo": "pergunta", "frente": "O que diz a RGI 3 b para produtos misturados ou sortidos?", "verso": "Classificam-se pela matéria ou artigo que lhes confere a característica essencial.", "explicacao": "Aplicada quando a RGI 3 a não resolve."}, {"id": 2000004304, "trilha": "fiscal", "materia": "adua", "assunto": "Tributos", "tipo": "pergunta", "frente": "Qual o fato gerador do ICMS na importação?", "verso": "O desembaraço aduaneiro.", "explicacao": "LC 87/1996, art. 12, IX."}, {"id": 2000004305, "trilha": "fiscal", "materia": "adua", "assunto": "Tributos", "tipo": "pergunta", "frente": "Como se calcula, em regra, o ICMS na importação?", "verso": "Por dentro: inclui o próprio ICMS na base, que soma o valor aduaneiro, II, IPI, PIS/Cofins-Importação e despesas aduaneiras.", "explicacao": "LC 87/1996, art. 13, V."}, {"id": 2000004306, "trilha": "fiscal", "materia": "adua", "assunto": "Tributos", "tipo": "pergunta", "frente": "O que é a Taxa de Utilização do Siscomex?", "verso": "Taxa cobrada no registro da declaração de importação.", "explicacao": "Lei 9.716/1998, art. 3º."}, {"id": 2000004307, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "pergunta", "frente": "O que é o Reporto?", "verso": "Regime tributário para modernização da infraestrutura portuária e ferroviária, com suspensão de tributos na compra de equipamentos.", "explicacao": "Lei 11.033/2004."}, {"id": 2000004308, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "pergunta", "frente": "O que é o regime de loja franca (free shop)?", "verso": "Venda de mercadorias nacionais ou estrangeiras com suspensão de tributos, em zona primária de portos e aeroportos, a viajantes.", "explicacao": "Regulamento Aduaneiro, art. 476."}, {"id": 2000004309, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "pergunta", "frente": "O que é o depósito afiançado?", "verso": "Regime que permite estocar, com suspensão de tributos, materiais de manutenção e reparo de embarcações e aeronaves de empresas estrangeiras de transporte internacional.", "explicacao": "Regulamento Aduaneiro, art. 488."}, {"id": 2000004310, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "pergunta", "frente": "O que é o Recof-Sped?", "verso": "Variante do entreposto industrial sob controle informatizado, com controle baseado nos dados do Sped.", "explicacao": "Permite importar insumos com suspensão de tributos para industrialização."}, {"id": 2000004311, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "pergunta", "frente": "O que é o regime de exportação temporária para aperfeiçoamento passivo?", "verso": "Saída temporária de mercadoria para conserto, reparo ou industrialização no exterior, com tributos cobrados só sobre o valor agregado no retorno.", "explicacao": "Regulamento Aduaneiro, art. 449."}, {"id": 2000004312, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "pergunta", "frente": "Qual a principal condição do drawback isenção?", "verso": "Repor estoque de insumos já usados na produção de bens exportados, com isenção de tributos na nova importação.", "explicacao": "Na suspensão, os insumos ainda serão usados na exportação."}, {"id": 2000004313, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "Quais são as penalidades aduaneiras previstas?", "verso": "Perdimento da mercadoria ou do veículo, multa, sanções administrativas (advertência, suspensão, cancelamento de habilitação) e outras.", "explicacao": "Regulamento Aduaneiro, art. 675."}, {"id": 2000004314, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "Qual a multa por falta de licença de importação, quando exigida?", "verso": "30% do valor aduaneiro da mercadoria.", "explicacao": "Regulamento Aduaneiro, art. 706, I, a."}, {"id": 2000004315, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "Qual a multa pela classificação incorreta da mercadoria na NCM?", "verso": "1% do valor aduaneiro, observados os limites mínimo e máximo previstos.", "explicacao": "Medida Provisória 2.158-35/2001, art. 84."}, {"id": 2000004316, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "O que é o descaminho por falsa declaração de conteúdo?", "verso": "Declarar uma mercadoria como sendo outra para iludir o pagamento de tributos, punível com perdimento.", "explicacao": "Decreto-Lei 1.455/1976, art. 23."}, {"id": 2000004317, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio internacional", "tipo": "pergunta", "frente": "Qual a diferença entre zona de livre comércio, união aduaneira e mercado comum?", "verso": "Livre comércio: elimina tarifas entre os membros. União aduaneira: soma tarifa externa comum. Mercado comum: soma livre circulação de pessoas, serviços e capitais.", "explicacao": "O Mercosul é uma união aduaneira imperfeita."}, {"id": 2000004318, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio internacional", "tipo": "pergunta", "frente": "Quais são os membros plenos do Mercosul?", "verso": "Argentina, Brasil, Paraguai, Uruguai e, desde 2024, a Bolívia. A Venezuela está suspensa.", "explicacao": "Tratado de Assunção (1991)."}, {"id": 2000004319, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio internacional", "tipo": "pergunta", "frente": "O que é o princípio do tratamento nacional na OMC?", "verso": "Depois de entrar no país, o produto importado deve receber o mesmo tratamento tributário e regulatório do produto nacional.", "explicacao": "GATT, art. III."}, {"id": 2000004320, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio internacional", "tipo": "pergunta", "frente": "O que são barreiras não tarifárias?", "verso": "Restrições ao comércio que não são tarifas, como cotas, licenças, exigências técnicas e sanitárias.", "explicacao": "Podem ser legítimas (saúde) ou protecionistas."}, {"id": 2000004321, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio internacional", "tipo": "pergunta", "frente": "Qual Incoterm é usado só no transporte marítimo e coloca o risco no comprador quando a mercadoria é posta ao lado do navio?", "verso": "FAS (Free Alongside Ship).", "explicacao": "Incoterms marítimos: FAS, FOB, CFR e CIF."}, {"id": 2000004322, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio internacional", "tipo": "pergunta", "frente": "No Incoterm FCA, onde o vendedor entrega a mercadoria?", "verso": "Ao transportador indicado pelo comprador, em local combinado, já desembaraçada para exportação.", "explicacao": "Usado em qualquer modal."}, {"id": 2000004323, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio internacional", "tipo": "pergunta", "frente": "Qual órgão decide a aplicação de direitos antidumping no Brasil?", "verso": "O Gecex da Camex, com investigação conduzida pelo Departamento de Defesa Comercial (Decom).", "explicacao": "Os direitos são cobrados pela Receita Federal."}, {"id": 2000004324, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Qual a média de 2, 4, 4, 5, 7, 8?", "verso": "5.", "explicacao": "Soma 30 ÷ 6."}, {"id": 2000004325, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Qual a variância populacional de 2, 4, 6?", "verso": "8/3 (cerca de 2,67).", "explicacao": "Média 4; desvios ao quadrado: 4, 0, 4; soma 8 ÷ 3."}, {"id": 2000004326, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Um conjunto tem média 50 e desvio padrão 5. Qual o coeficiente de variação?", "verso": "10%.", "explicacao": "CV = 5 ÷ 50."}, {"id": 2000004327, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Se a média de 10 valores é 20, qual a soma desses valores?", "verso": "200.", "explicacao": "Soma = média × n."}, {"id": 2000004328, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Uma turma de 20 alunos tem média 6 e outra de 30 alunos tem média 8. Qual a média geral?", "verso": "7,2.", "explicacao": "(20 × 6 + 30 × 8) ÷ 50 = 360 ÷ 50."}, {"id": 2000004329, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Em dados agrupados, como se encontra a classe modal?", "verso": "É a classe com maior frequência.", "explicacao": "A moda bruta é o ponto médio da classe modal."}, {"id": 2000004330, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "O que é o desvio médio absoluto?", "verso": "A média dos valores absolutos dos desvios em relação à média.", "explicacao": "Menos usado que o desvio padrão."}, {"id": 2000004331, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Quais as medidas separatrizes?", "verso": "Quartis (4 partes), decis (10 partes) e percentis (100 partes).", "explicacao": "A mediana é o 2º quartil, o 5º decil e o 50º percentil."}, {"id": 2000004332, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "O que indica um boxplot com a mediana mais próxima do 1º quartil?", "verso": "Assimetria positiva (à direita).", "explicacao": "A cauda longa fica do lado dos valores maiores."}, {"id": 2000004333, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "Como se identificam outliers pelo critério do boxplot?", "verso": "Valores abaixo de Q1 − 1,5 × AIQ ou acima de Q3 + 1,5 × AIQ.", "explicacao": "AIQ = Q3 − Q1."}, {"id": 2000004334, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "O que é a média harmônica e quando se usa?", "verso": "O inverso da média dos inversos. Usada para médias de taxas, como velocidade média em trechos de mesma distância.", "explicacao": "Ex.: ida a 60 km/h e volta a 40 km/h: média de 48 km/h."}, {"id": 2000004335, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "O que acontece com o coeficiente de variação se todos os valores forem multiplicados por 2?", "verso": "Não muda.", "explicacao": "Média e desvio dobram juntos."}, {"id": 2000004336, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Em um baralho de 52 cartas, qual a probabilidade de tirar um ás?", "verso": "1/13.", "explicacao": "4 ases ÷ 52 cartas."}, {"id": 2000004337, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Se P(A) = 0,4, P(B) = 0,5 e A e B são independentes, qual P(A ∩ B)?", "verso": "0,2.", "explicacao": "0,4 × 0,5."}, {"id": 2000004338, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Se P(A) = 0,4, P(B) = 0,5 e P(A ∩ B) = 0,2, qual P(A ∪ B)?", "verso": "0,7.", "explicacao": "0,4 + 0,5 − 0,2."}, {"id": 2000004339, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a probabilidade de, em 3 lançamentos de uma moeda, sair exatamente 2 caras?", "verso": "3/8.", "explicacao": "C(3,2) × (1/2)³ = 3/8 (binomial)."}, {"id": 2000004340, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a média e a variância da distribuição binomial?", "verso": "Média = n × p. Variância = n × p × (1 − p).", "explicacao": "Ex.: n = 100 e p = 0,5: média 50 e variância 25."}, {"id": 2000004341, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a média e a variância da distribuição de Poisson?", "verso": "Ambas iguais a λ (lambda).", "explicacao": "Usada para contagem de eventos raros por intervalo."}, {"id": 2000004342, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Qual a média de uma variável uniforme contínua entre a e b?", "verso": "(a + b) ÷ 2.", "explicacao": "Variância: (b − a)² ÷ 12."}, {"id": 2000004343, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "O que é a distribuição exponencial?", "verso": "Distribuição contínua do tempo entre eventos de um processo de Poisson, sem memória.", "explicacao": "Média = 1 ÷ λ."}, {"id": 2000004344, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Se X tem média 10 e variância 4, quais a média e a variância de Y = 3X + 2?", "verso": "Média 32 e variância 36.", "explicacao": "E(3X + 2) = 3 × 10 + 2; Var = 3² × 4."}, {"id": 2000004345, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Qual o valor de z para um intervalo de confiança de 95% na normal?", "verso": "1,96.", "explicacao": "Para 90%, 1,645; para 99%, 2,576."}, {"id": 2000004346, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Qual o erro padrão da média para σ = 10 e n = 100?", "verso": "1.", "explicacao": "σ ÷ √n = 10 ÷ 10."}, {"id": 2000004347, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Qual o tamanho de amostra necessário para estimar uma proporção com erro de 5% e 95% de confiança, no pior caso?", "verso": "Cerca de 385.", "explicacao": "n = z² × p × (1 − p) ÷ E² = 1,96² × 0,25 ÷ 0,0025 ≈ 384,2."}, {"id": 2000004348, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "O que é o nível de significância (α)?", "verso": "A probabilidade máxima aceita de cometer erro tipo I (rejeitar H0 verdadeira).", "explicacao": "Comuns: 5% e 1%."}, {"id": 2000004349, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "O que é o poder de um teste?", "verso": "A probabilidade de rejeitar H0 quando ela é falsa: 1 − β.", "explicacao": "Aumenta com o tamanho da amostra."}, {"id": 2000004350, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Quando se rejeita H0 pelo p-valor?", "verso": "Quando o p-valor é menor que o nível de significância α.", "explicacao": "Ex.: p = 0,03 < 0,05 → rejeita H0."}, {"id": 2000004351, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Quando se usa a distribuição F de Snedecor?", "verso": "Para comparar variâncias e na análise de variância (ANOVA).", "explicacao": "Razão entre duas qui-quadrado divididas por seus graus de liberdade."}, {"id": 2000004352, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "O que testa a ANOVA de um fator?", "verso": "Se as médias de três ou mais grupos são iguais.", "explicacao": "Compara a variância entre grupos com a variância dentro dos grupos."}, {"id": 2000004353, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "O que testa o qui-quadrado de independência?", "verso": "Se duas variáveis categóricas são independentes, comparando frequências observadas e esperadas numa tabela de contingência.", "explicacao": "Graus de liberdade: (linhas − 1) × (colunas − 1)."}, {"id": 2000004354, "trilha": "fiscal", "materia": "est", "assunto": "Regressão", "tipo": "pergunta", "frente": "Qual a fórmula do coeficiente angular b na regressão linear simples por mínimos quadrados?", "verso": "b = Cov(X, Y) ÷ Var(X).", "explicacao": "O intercepto é a = ȳ − b × x̄."}, {"id": 2000004355, "trilha": "fiscal", "materia": "est", "assunto": "Regressão", "tipo": "pergunta", "frente": "Na regressão simples, qual a relação entre R² e o coeficiente de correlação r?", "verso": "R² = r².", "explicacao": "Ex.: r = 0,8 → R² = 0,64 (64% da variação explicada)."}, {"id": 2000004356, "trilha": "fiscal", "materia": "est", "assunto": "Regressão", "tipo": "pergunta", "frente": "O que são resíduos na regressão?", "verso": "As diferenças entre os valores observados e os previstos pelo modelo.", "explicacao": "Devem ser aleatórios, com média zero."}, {"id": 2000004357, "trilha": "fiscal", "materia": "est", "assunto": "Regressão", "tipo": "pergunta", "frente": "O que é heterocedasticidade?", "verso": "Quando a variância dos resíduos não é constante ao longo dos valores de X.", "explicacao": "Viola um pressuposto do modelo clássico."}, {"id": 2000004358, "trilha": "fiscal", "materia": "est", "assunto": "Regressão", "tipo": "pergunta", "frente": "O que é autocorrelação dos resíduos?", "verso": "Quando os resíduos de observações próximas (em geral no tempo) são correlacionados.", "explicacao": "Testada por Durbin-Watson."}, {"id": 2000004359, "trilha": "fiscal", "materia": "est", "assunto": "Números-índices", "tipo": "pergunta", "frente": "Um preço passou de R$ 40 para R$ 50. Qual o índice simples com base no primeiro?", "verso": "125.", "explicacao": "50 ÷ 40 × 100."}, {"id": 2000004360, "trilha": "fiscal", "materia": "est", "assunto": "Séries temporais", "tipo": "pergunta", "frente": "O que é sazonalidade em séries temporais?", "verso": "Variações que se repetem em períodos fixos, como meses ou estações.", "explicacao": "Ex.: vendas maiores em dezembro."}, {"id": 2000004361, "trilha": "fiscal", "materia": "est", "assunto": "Amostragem", "tipo": "pergunta", "frente": "O que é o fator de correção para população finita?", "verso": "Ajuste do erro padrão quando a amostra é grande em relação à população: √[(N − n) ÷ (N − 1)].", "explicacao": "Desprezível quando n é menos de 5% de N."}, {"id": 2000004362, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz o comando UPDATE?", "verso": "Altera valores de registros existentes. Sem WHERE, altera todas as linhas.", "explicacao": "Ex.: UPDATE clientes SET uf = 'BA' WHERE id = 10;"}, {"id": 2000004363, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz o operador LIKE com '%'?", "verso": "Busca padrões em textos: '%' substitui qualquer sequência de caracteres e '_' um único caractere.", "explicacao": "Ex.: WHERE nome LIKE 'Ana%'."}, {"id": 2000004364, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz o ORDER BY ... DESC?", "verso": "Ordena o resultado em ordem decrescente.", "explicacao": "ASC (padrão) é crescente."}, {"id": 2000004365, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz o operador IN?", "verso": "Testa se o valor está em uma lista ou no resultado de uma subconsulta.", "explicacao": "Ex.: WHERE uf IN ('BA', 'PE')."}, {"id": 2000004366, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz o BETWEEN?", "verso": "Filtra valores dentro de um intervalo, incluindo os extremos.", "explicacao": "Ex.: WHERE valor BETWEEN 100 AND 200."}, {"id": 2000004367, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "Como se testa valor nulo em SQL?", "verso": "Com IS NULL ou IS NOT NULL, nunca com = NULL.", "explicacao": "NULL representa ausência de valor."}, {"id": 2000004368, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz UNION x UNION ALL?", "verso": "Ambos juntam resultados de consultas. UNION elimina linhas repetidas; UNION ALL mantém todas.", "explicacao": "As consultas devem ter as mesmas colunas compatíveis."}, {"id": 2000004369, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que é uma VIEW?", "verso": "Uma consulta salva que funciona como tabela virtual.", "explicacao": "Simplifica consultas e restringe acesso a dados."}, {"id": 2000004370, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que é um índice em banco de dados?", "verso": "Estrutura que acelera a busca de registros, ao custo de mais espaço e escrita mais lenta.", "explicacao": "Funciona como o índice de um livro."}, {"id": 2000004371, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que fazem GRANT e REVOKE?", "verso": "Concedem e retiram permissões de acesso a usuários.", "explicacao": "Comandos da DCL."}, {"id": 2000004372, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que fazem COMMIT e ROLLBACK?", "verso": "COMMIT confirma a transação; ROLLBACK desfaz as alterações não confirmadas.", "explicacao": "Comandos de controle de transação."}, {"id": 2000004373, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que é FULL OUTER JOIN?", "verso": "Retorna todas as linhas das duas tabelas, com correspondência quando houver e nulos quando não houver.", "explicacao": "Combina LEFT e RIGHT JOIN."}, {"id": 2000004374, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que é uma subconsulta (subquery)?", "verso": "Uma consulta dentro de outra, usada em WHERE, FROM ou SELECT.", "explicacao": "Ex.: clientes com compras acima da média."}, {"id": 2000004375, "trilha": "fiscal", "materia": "dados", "assunto": "Modelagem", "tipo": "pergunta", "frente": "O que é o modelo entidade-relacionamento (MER)?", "verso": "Modelo conceitual que representa entidades, atributos e relacionamentos entre elas.", "explicacao": "Representado no diagrama DER."}, {"id": 2000004376, "trilha": "fiscal", "materia": "dados", "assunto": "Modelagem", "tipo": "pergunta", "frente": "O que significa cardinalidade 1:N?", "verso": "Um registro de uma entidade se relaciona com vários da outra, como um cliente com vários pedidos.", "explicacao": "Também há 1:1 e N:N."}, {"id": 2000004377, "trilha": "fiscal", "materia": "dados", "assunto": "Modelagem", "tipo": "pergunta", "frente": "Como se implementa um relacionamento N:N no modelo relacional?", "verso": "Com uma tabela associativa, que contém as chaves estrangeiras das duas tabelas.", "explicacao": "Ex.: alunos e disciplinas → tabela matrículas."}, {"id": 2000004378, "trilha": "fiscal", "materia": "dados", "assunto": "Modelagem", "tipo": "pergunta", "frente": "O que exige a primeira forma normal (1FN)?", "verso": "Atributos atômicos, sem grupos repetidos ou valores multivalorados.", "explicacao": "2FN: sem dependência parcial; 3FN: sem dependência transitiva."}, {"id": 2000004379, "trilha": "fiscal", "materia": "dados", "assunto": "Modelagem", "tipo": "pergunta", "frente": "O que é desnormalização?", "verso": "Introduzir redundância de propósito para ganhar desempenho em consultas, comum em data warehouses.", "explicacao": "Troca integridade por velocidade de leitura."}, {"id": 2000004380, "trilha": "fiscal", "materia": "dados", "assunto": "BI", "tipo": "pergunta", "frente": "O que é o modelo estrela (star schema)?", "verso": "Modelo dimensional com uma tabela fato central ligada a várias tabelas de dimensão.", "explicacao": "O floco de neve normaliza as dimensões."}, {"id": 2000004381, "trilha": "fiscal", "materia": "dados", "assunto": "BI", "tipo": "pergunta", "frente": "O que é slice and dice no OLAP?", "verso": "Slice: fixar um valor de uma dimensão (fatia). Dice: selecionar um subcubo com filtros em várias dimensões.", "explicacao": "Pivot gira as dimensões."}, {"id": 2000004382, "trilha": "fiscal", "materia": "dados", "assunto": "BI", "tipo": "pergunta", "frente": "O que é um KPI?", "verso": "Indicador-chave de desempenho, que mede o alcance de um objetivo.", "explicacao": "Ex.: arrecadação por auditor, tempo médio de análise."}, {"id": 2000004383, "trilha": "fiscal", "materia": "dados", "assunto": "BI", "tipo": "pergunta", "frente": "O que é ELT, em comparação com ETL?", "verso": "No ELT, os dados são carregados primeiro no destino (como um data lake) e transformados depois.", "explicacao": "Comum em ambientes de nuvem."}, {"id": 2000004384, "trilha": "fiscal", "materia": "dados", "assunto": "Big data", "tipo": "pergunta", "frente": "O que é o Hadoop?", "verso": "Plataforma de código aberto para armazenar e processar grandes volumes de dados de forma distribuída (HDFS e MapReduce).", "explicacao": "O Spark processa em memória, mais rápido."}, {"id": 2000004385, "trilha": "fiscal", "materia": "dados", "assunto": "Big data", "tipo": "pergunta", "frente": "O que é processamento em lote (batch) x em fluxo (streaming)?", "verso": "Lote: processa grandes conjuntos acumulados de tempos em tempos. Streaming: processa os dados continuamente, à medida que chegam.", "explicacao": "Streaming é usado para detecção de fraude em tempo real."}, {"id": 2000004386, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "O que é a validação cruzada (k-fold)?", "verso": "Dividir os dados em k partes e treinar k vezes, cada vez testando em uma parte diferente, para avaliar o modelo de forma robusta.", "explicacao": "Ajuda a detectar overfitting."}, {"id": 2000004387, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "O que é a acurácia de um modelo de classificação?", "verso": "A proporção de acertos sobre o total: (VP + VN) ÷ total.", "explicacao": "Pode enganar em classes desbalanceadas."}, {"id": 2000004388, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "O que é o F1-score?", "verso": "A média harmônica entre precisão e recall.", "explicacao": "Útil em classes desbalanceadas, como fraudes."}, {"id": 2000004389, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "O que é uma árvore de decisão?", "verso": "Modelo que divide os dados em regras sucessivas (se... então), fácil de interpretar.", "explicacao": "Base de modelos como random forest."}, {"id": 2000004390, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "O que é o algoritmo k-means?", "verso": "Algoritmo de agrupamento que separa os dados em k grupos pela proximidade aos centros (centroides).", "explicacao": "Aprendizado não supervisionado."}, {"id": 2000004391, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "O que é regressão logística?", "verso": "Modelo de classificação que estima a probabilidade de um evento binário (sim ou não).", "explicacao": "Apesar do nome, é usada para classificação."}, {"id": 2000004392, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "O que é viés (bias) e variância em aprendizado de máquina?", "verso": "Viés alto: modelo simples demais (underfitting). Variância alta: modelo sensível demais aos dados de treino (overfitting).", "explicacao": "Busca-se o equilíbrio."}, {"id": 2000004393, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "pergunta", "frente": "Para que se usa a análise de anomalias na fiscalização?", "verso": "Para identificar comportamentos fora do padrão, como declarações inconsistentes, que podem indicar sonegação ou fraude.", "explicacao": "Apoia a seleção de contribuintes para auditoria."}, {"id": 2000004394, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "Quais os direitos do titular na LGPD?", "verso": "Confirmação e acesso aos dados, correção, anonimização, bloqueio ou eliminação, portabilidade, informação sobre compartilhamento e revogação do consentimento, entre outros.", "explicacao": "LGPD, art. 18."}, {"id": 2000004395, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "O que é o relatório de impacto à proteção de dados?", "verso": "Documento do controlador que descreve os tratamentos que podem gerar riscos e as medidas para mitigá-los.", "explicacao": "LGPD, art. 5º, XVII, e art. 38."}, {"id": 2000004396, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "Quais os princípios da LGPD?", "verso": "Finalidade, adequação, necessidade, livre acesso, qualidade dos dados, transparência, segurança, prevenção, não discriminação e responsabilização.", "explicacao": "LGPD, art. 6º."}, {"id": 2000004397, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "Em quanto tempo o controlador deve comunicar incidente de segurança à ANPD?", "verso": "Em prazo razoável; o regulamento da ANPD fixa 3 dias úteis, em regra.", "explicacao": "LGPD, art. 48, e Resolução CD/ANPD 15/2024."}, {"id": 2000004398, "trilha": "fiscal", "materia": "dados", "assunto": "Governança", "tipo": "pergunta", "frente": "O que é a Infraestrutura Nacional de Dados (IND)?", "verso": "Conjunto de normas, políticas e ferramentas para o compartilhamento e uso de dados no governo federal.", "explicacao": "Decreto 10.046/2019 (governança no compartilhamento de dados)."}, {"id": 2000004399, "trilha": "fiscal", "materia": "dados", "assunto": "Governança", "tipo": "pergunta", "frente": "O que é catálogo de dados?", "verso": "Inventário dos dados da organização, com metadados que facilitam encontrar e entender cada conjunto.", "explicacao": "Instrumento de governança."}, {"id": 2000004400, "trilha": "fiscal", "materia": "dados", "assunto": "Visualização", "tipo": "pergunta", "frente": "Qual gráfico é mais indicado para mostrar a relação entre duas variáveis numéricas?", "verso": "O gráfico de dispersão.", "explicacao": "Ajuda a ver correlação e outliers."}, {"id": 2000004401, "trilha": "fiscal", "materia": "dados", "assunto": "Visualização", "tipo": "pergunta", "frente": "Qual gráfico é mais indicado para comparar categorias?", "verso": "O gráfico de barras.", "explicacao": "Pizza só para poucas partes de um todo."}, {"id": 2000004402, "trilha": "fiscal", "materia": "dados", "assunto": "Python", "tipo": "pergunta", "frente": "Qual biblioteca do Python é mais usada para manipular tabelas de dados?", "verso": "Pandas.", "explicacao": "Com DataFrames. NumPy para cálculo numérico."}, {"id": 2000004403, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "O IR pode ser exigido sobre indenizações?", "verso": "Em regra não, porque indenização recompõe patrimônio e não é acréscimo patrimonial.", "explicacao": "Ex.: Súmula 498 do STJ (danos morais) e Súmula 215 (PDV)."}, {"id": 2000004404, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos federais", "tipo": "pergunta", "frente": "O que são as contribuições de intervenção no domínio econômico (Cide)?", "verso": "Contribuições da União para intervir em setores da economia, como a Cide-combustíveis.", "explicacao": "CF, art. 149 e art. 177, § 4º."}, {"id": 2000004405, "trilha": "fiscal", "materia": "trib", "assunto": "Contribuições", "tipo": "pergunta", "frente": "As contribuições sociais para a seguridade obedecem a qual anterioridade?", "verso": "Só à nonagesimal (90 dias), e não à anterioridade de exercício.", "explicacao": "CF, art. 195, § 6º."}, {"id": 2000004406, "trilha": "fiscal", "materia": "trib", "assunto": "Contribuições", "tipo": "pergunta", "frente": "Os municípios podem instituir contribuição para custeio da iluminação pública?", "verso": "Sim. A COSIP pode ser cobrada na fatura de energia.", "explicacao": "CF, art. 149-A. A EC 132/2023 ampliou para sistemas de monitoramento de segurança."}, {"id": 2000004407, "trilha": "fiscal", "materia": "trib", "assunto": "Taxas", "tipo": "pergunta", "frente": "Qual a diferença entre taxa e preço público (tarifa)?", "verso": "Taxa é tributo compulsório, instituído por lei. Preço público é voluntário, decorre de contrato.", "explicacao": "Súmula 545 do STF."}, {"id": 2000004408, "trilha": "fiscal", "materia": "trib", "assunto": "Obrigação tributária", "tipo": "pergunta", "frente": "Quando ocorre o fato gerador em situação de fato?", "verso": "Desde o momento em que se verifiquem as circunstâncias materiais necessárias para que produza os efeitos próprios.", "explicacao": "CTN, art. 116, I. Em situação jurídica, desde que esteja definitivamente constituída (II)."}, {"id": 2000004409, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Como se registra a venda de mercadorias à vista pelo inventário permanente?", "verso": "D Caixa / C Receita de vendas; e D CMV / C Mercadorias, pelo custo.", "explicacao": "Registro do custo a cada venda."}, {"id": 2000004410, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Como se registra a reversão de PECLD não utilizada?", "verso": "D PECLD / C Reversão de provisão (receita).", "explicacao": "Ou ajuste direto contra a despesa do período."}, {"id": 2000004411, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Como se registra a baixa de um cliente incobrável com PECLD constituída?", "verso": "D PECLD / C Clientes.", "explicacao": "Não afeta o resultado, pois a perda já foi reconhecida."}, {"id": 2000004412, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Como se registra o seguro pago antecipadamente por 12 meses?", "verso": "D Seguros a apropriar (ativo) / C Caixa. A cada mês: D Despesa de seguros / C Seguros a apropriar.", "explicacao": "Regime de competência."}, {"id": 2000004413, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é despesa pública empenhada e não liquidada no fim do ano?", "verso": "É inscrita em restos a pagar não processados.", "explicacao": "Lei 4.320/1964, art. 36."}, {"id": 2000004414, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "Por que a dívida ativa não é receita orçamentária no momento da inscrição?", "verso": "Porque a receita orçamentária, pela Lei 4.320, é reconhecida na arrecadação. A inscrição gera ativo (VPA) na contabilidade patrimonial.", "explicacao": "Lei 4.320/1964, art. 35 e art. 39."}, {"id": 2000004415, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "pergunta", "frente": "O que é um bem de Giffen?", "verso": "Bem inferior cuja demanda aumenta quando o preço sobe, porque o efeito renda supera o efeito substituição.", "explicacao": "Exceção teórica à lei da demanda."}, {"id": 2000004416, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "pergunta", "frente": "O que é poupança privada, pública e externa?", "verso": "Privada: renda disponível menos consumo. Pública: receitas menos gastos do governo. Externa: déficit em transações correntes.", "explicacao": "Investimento = soma das três poupanças."}, {"id": 2000004417, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que é o teste de \"walkthrough\"?", "verso": "Acompanhar uma transação do início ao fim no sistema de registro, para entender o processo e verificar se os controles foram implementados.", "explicacao": "Usado no entendimento do controle interno."}, {"id": 2000004418, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "O que o auditor deve fazer se descobrir, após a emissão do relatório, fato que teria levado a alteração?", "verso": "Discutir com a administração, verificar se as demonstrações serão alteradas e, se for o caso, emitir novo relatório.", "explicacao": "NBC TA 560."}, {"id": 2000004419, "trilha": "fiscal", "materia": "trib", "assunto": "Conceitos", "tipo": "certo_errado", "frente": "Certo ou errado? O tributo pode ser pago em bens, se a lei permitir.", "verso": "Certo. O CTN fala em prestação \"em moeda ou cujo valor nela se possa exprimir\", e a lei pode admitir a dação de imóveis.", "explicacao": "CTN, arts. 3º e 156, XI."}, {"id": 2000004420, "trilha": "fiscal", "materia": "trib", "assunto": "Competência", "tipo": "certo_errado", "frente": "Certo ou errado? A competência tributária pode ser delegada a outro ente.", "verso": "Errado. É indelegável. Só a capacidade tributária ativa (arrecadar e fiscalizar) pode ser delegada.", "explicacao": "CTN, art. 7º."}, {"id": 2000004421, "trilha": "fiscal", "materia": "trib", "assunto": "Competência", "tipo": "certo_errado", "frente": "Certo ou errado? O não exercício da competência tributária por um ente permite que outro ente a exerça.", "verso": "Errado.", "explicacao": "CTN, art. 8º."}, {"id": 2000004422, "trilha": "fiscal", "materia": "trib", "assunto": "Princípios", "tipo": "certo_errado", "frente": "Certo ou errado? A majoração do IPI precisa esperar o exercício seguinte.", "verso": "Errado. O IPI é exceção à anterioridade de exercício, mas respeita a noventena.", "explicacao": "CF, art. 150, § 1º."}, {"id": 2000004423, "trilha": "fiscal", "materia": "trib", "assunto": "Imunidades", "tipo": "certo_errado", "frente": "Certo ou errado? As imunidades do art. 150, VI, da CF alcançam também as taxas.", "verso": "Errado. Alcançam apenas impostos.", "explicacao": "Por isso templos pagam taxa de coleta de lixo, por exemplo."}, {"id": 2000004424, "trilha": "fiscal", "materia": "trib", "assunto": "Imunidades", "tipo": "certo_errado", "frente": "Certo ou errado? A imunidade recíproca alcança as empresas estatais que prestam serviço público em regime de monopólio, como os Correios.", "verso": "Certo, segundo o STF.", "explicacao": "RE 601.392 e precedentes sobre a ECT."}, {"id": 2000004425, "trilha": "fiscal", "materia": "trib", "assunto": "Sujeição passiva", "tipo": "certo_errado", "frente": "Certo ou errado? Um contrato entre particulares pode transferir ao locatário a obrigação de pagar o IPTU perante o município.", "verso": "Errado. O contrato vale entre as partes, mas não pode ser oposto à Fazenda.", "explicacao": "CTN, art. 123."}, {"id": 2000004426, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "certo_errado", "frente": "Certo ou errado? O parcelamento extingue o crédito tributário.", "verso": "Errado. Suspende a exigibilidade.", "explicacao": "CTN, art. 151, VI. Extingue só com o pagamento integral."}, {"id": 2000004427, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "certo_errado", "frente": "Certo ou errado? A imposição de multa exclui o pagamento integral do tributo.", "verso": "Errado. A multa não elide o pagamento do tributo.", "explicacao": "CTN, art. 157."}, {"id": 2000004428, "trilha": "fiscal", "materia": "trib", "assunto": "Crédito tributário", "tipo": "certo_errado", "frente": "Certo ou errado? O pagamento de uma parcela presume o pagamento das anteriores.", "verso": "Errado. O pagamento de uma parcela não importa presunção de pagamento das demais.", "explicacao": "CTN, art. 158."}, {"id": 2000004429, "trilha": "fiscal", "materia": "trib", "assunto": "Exclusão do crédito", "tipo": "lacuna", "frente": "\"A isenção, ainda quando prevista em contrato, é sempre decorrente de ____.\"", "verso": "lei", "explicacao": "CTN, art. 176."}, {"id": 2000004430, "trilha": "fiscal", "materia": "trib", "assunto": "Legislação tributária", "tipo": "lacuna", "frente": "\"Salvo disposição em contrário, os atos normativos expedidos pelas autoridades administrativas entram em vigor ____ dias após a sua publicação.\"", "verso": "30", "explicacao": "CTN, art. 103, I."}, {"id": 2000004431, "trilha": "fiscal", "materia": "trib", "assunto": "Reforma tributária", "tipo": "certo_errado", "frente": "Certo ou errado? O IBS será cobrado no estado de origem da mercadoria.", "verso": "Errado. Segue o princípio do destino.", "explicacao": "EC 132/2023."}, {"id": 2000004432, "trilha": "fiscal", "materia": "trib", "assunto": "Regimes", "tipo": "certo_errado", "frente": "Certo ou errado? A empresa do Simples Nacional recolhe vários tributos em uma única guia (DAS).", "verso": "Certo.", "explicacao": "LC 123/2006, art. 13."}, {"id": 2000004433, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos municipais", "tipo": "certo_errado", "frente": "Certo ou errado? O município pode conceder isenção de ISS por meio de convênio do Confaz.", "verso": "Errado. O Confaz trata de benefícios de ICMS. O ISS é regido pela lei municipal, observada a alíquota mínima de 2%.", "explicacao": "ADCT, art. 88."}, {"id": 2000004434, "trilha": "fiscal", "materia": "trib", "assunto": "Impostos estaduais", "tipo": "pares", "frente": "Qual a diferença entre ICMS por dentro e por fora?", "verso": "Por dentro: o imposto integra sua própria base de cálculo (como no ICMS). Por fora: é calculado sobre o preço sem incluí-lo (como no IPI).", "explicacao": "LC 87/1996, art. 13, § 1º."}, {"id": 2000004435, "trilha": "fiscal", "materia": "cont", "assunto": "Fundamentos", "tipo": "certo_errado", "frente": "Certo ou errado? A contabilidade deve registrar apenas os fatos que envolvem dinheiro.", "verso": "Errado. Registra todos os fatos que alteram o patrimônio, como depreciação e provisões.", "explicacao": "Regime de competência."}, {"id": 2000004436, "trilha": "fiscal", "materia": "cont", "assunto": "Fundamentos", "tipo": "certo_errado", "frente": "Certo ou errado? O regime de caixa é o exigido pela Lei 6.404 para o resultado.", "verso": "Errado. O exigido é o regime de competência.", "explicacao": "Lei 6.404/1976, art. 177."}, {"id": 2000004437, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "certo_errado", "frente": "Certo ou errado? Toda conta devedora é de ativo.", "verso": "Errado. Despesas também são contas de natureza devedora, assim como as redutoras do passivo.", "explicacao": "Natureza das contas."}, {"id": 2000004438, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "lacuna", "frente": "\"No método das partidas dobradas, a todo débito corresponde um ____ de igual valor.\"", "verso": "crédito", "explicacao": "Base da escrituração."}, {"id": 2000004439, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "certo_errado", "frente": "Certo ou errado? Pelo CPC 16, a empresa pode usar o UEPS para avaliar os estoques.", "verso": "Errado. O UEPS não é permitido.", "explicacao": "CPC 16. Admitidos: custo específico, PEPS e média ponderada."}, {"id": 2000004440, "trilha": "fiscal", "materia": "cont", "assunto": "Imobilizado", "tipo": "certo_errado", "frente": "Certo ou errado? A depreciação é uma saída de caixa.", "verso": "Errado. É despesa econômica que não afeta o caixa.", "explicacao": "Por isso é somada de volta na DFC indireta."}, {"id": 2000004441, "trilha": "fiscal", "materia": "cont", "assunto": "Demonstrações", "tipo": "certo_errado", "frente": "Certo ou errado? A DVA é obrigatória para todas as sociedades anônimas.", "verso": "Errado. É obrigatória para as companhias abertas.", "explicacao": "Lei 6.404/1976, art. 176, V."}, {"id": 2000004442, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "certo_errado", "frente": "Certo ou errado? As ações em tesouraria aumentam o patrimônio líquido.", "verso": "Errado. São conta redutora do PL.", "explicacao": "Lei 6.404/1976, art. 182, § 5º."}, {"id": 2000004443, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "certo_errado", "frente": "Certo ou errado? Uma liquidez corrente menor que 1 indica que o ativo circulante não cobre o passivo circulante.", "verso": "Certo.", "explicacao": "Liquidez corrente = AC ÷ PC."}, {"id": 2000004444, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "certo_errado", "frente": "Certo ou errado? O custeio variável é aceito pelo fisco para apurar o IR.", "verso": "Errado. Para fins fiscais e societários, exige-se o custeio por absorção.", "explicacao": "O custeio variável é ferramenta gerencial."}, {"id": 2000004445, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "lacuna", "frente": "\"Margem de contribuição unitária = preço de venda − custos e despesas ____ unitários.\"", "verso": "variáveis", "explicacao": "Base do ponto de equilíbrio."}, {"id": 2000004446, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "certo_errado", "frente": "Certo ou errado? No setor público, a receita orçamentária é registrada pelo regime de competência.", "verso": "Errado. A receita orçamentária segue o regime de caixa (arrecadação). O regime de competência vale para o patrimonial (VPA).", "explicacao": "Lei 4.320/1964, art. 35, e MCASP."}, {"id": 2000004447, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "certo_errado", "frente": "Certo ou errado? O princípio da exclusividade proíbe que a LOA autorize abertura de créditos suplementares.", "verso": "Errado. Essa autorização é uma das exceções permitidas, junto com operações de crédito, inclusive por ARO.", "explicacao": "CF, art. 165, § 8º."}, {"id": 2000004448, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "certo_errado", "frente": "Certo ou errado? A vinculação de receita de impostos ao fundo de participação dos municípios viola o princípio da não afetação.", "verso": "Errado. É exceção constitucional expressa.", "explicacao": "CF, art. 167, IV."}, {"id": 2000004449, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "certo_errado", "frente": "Certo ou errado? O crédito extraordinário exige indicação prévia dos recursos.", "verso": "Errado. Por ser urgente e imprevisível, dispensa a indicação de recursos.", "explicacao": "Lei 4.320/1964, art. 43 e art. 44."}, {"id": 2000004450, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "certo_errado", "frente": "Certo ou errado? É possível realizar despesa sem prévio empenho, se houver urgência.", "verso": "Errado. É vedada a realização de despesa sem prévio empenho.", "explicacao": "Lei 4.320/1964, art. 60. A nota de empenho é que pode ser dispensada em casos especiais."}, {"id": 2000004451, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "certo_errado", "frente": "Certo ou errado? A compra de um imóvel já pronto e em uso é classificada como investimento.", "verso": "Errado. É inversão financeira, porque não aumenta o patrimônio do país, apenas transfere a propriedade.", "explicacao": "Lei 4.320/1964, art. 12, § 5º."}, {"id": 2000004452, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "certo_errado", "frente": "Certo ou errado? A LRF permite que o ente use recursos vinculados para despesa diversa da sua finalidade.", "verso": "Errado. Os recursos vinculados devem atender exclusivamente ao objeto da vinculação, ainda que em exercício diverso.", "explicacao": "LRF, art. 8º, parágrafo único."}, {"id": 2000004453, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "lacuna", "frente": "\"Para a LRF, despesa obrigatória de caráter continuado é a que fixa obrigação legal de execução por período superior a ____ exercícios.\"", "verso": "dois", "explicacao": "LRF, art. 17."}, {"id": 2000004454, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "certo_errado", "frente": "Certo ou errado? Os limites de despesa com pessoal da LRF são calculados sobre a receita corrente bruta.", "verso": "Errado. São calculados sobre a receita corrente líquida.", "explicacao": "LRF, arts. 19 e 20."}, {"id": 2000004455, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "lacuna", "frente": "\"Os estágios da receita orçamentária, pelo MCASP, são previsão, lançamento, ____ e recolhimento.\"", "verso": "arrecadação", "explicacao": "O lançamento nem sempre ocorre."}, {"id": 2000004456, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "certo_errado", "frente": "Certo ou errado? O objetivo da auditoria é descobrir fraudes.", "verso": "Errado. O objetivo é expressar opinião sobre as demonstrações; a detecção de fraude relevante é parte do trabalho, mas não o objetivo principal.", "explicacao": "NBC TA 200."}, {"id": 2000004457, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "certo_errado", "frente": "Certo ou errado? Evidência obtida diretamente pelo auditor é mais confiável que a obtida indiretamente.", "verso": "Certo.", "explicacao": "NBC TA 500, A31."}, {"id": 2000004458, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "certo_errado", "frente": "Certo ou errado? Uma cópia é tão confiável quanto o documento original.", "verso": "Errado. O original é mais confiável que fotocópias ou digitalizações.", "explicacao": "NBC TA 500, A31."}, {"id": 2000004459, "trilha": "fiscal", "materia": "aud", "assunto": "Risco", "tipo": "certo_errado", "frente": "Certo ou errado? O auditor pode reduzir o risco inerente com mais testes.", "verso": "Errado. O auditor não controla o risco inerente nem o de controle; ele atua sobre o risco de detecção.", "explicacao": "NBC TA 200."}, {"id": 2000004460, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "certo_errado", "frente": "Certo ou errado? O parágrafo de ênfase modifica a opinião do auditor.", "verso": "Errado. Só chama a atenção para assunto divulgado, sem modificar a opinião.", "explicacao": "NBC TA 706."}, {"id": 2000004461, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "certo_errado", "frente": "Certo ou errado? Um bom controle interno elimina totalmente o risco de fraude.", "verso": "Errado. O controle interno dá segurança razoável e tem limitações, como conluio e burla pela administração.", "explicacao": "Limitações inerentes."}, {"id": 2000004462, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "lacuna", "frente": "\"Distorções relevantes e generalizadas levam à opinião ____.\"", "verso": "adversa", "explicacao": "Relevantes e não generalizadas: com ressalva."}, {"id": 2000004463, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "certo_errado", "frente": "Certo ou errado? Se a demanda for perfeitamente inelástica, todo o imposto recai sobre o consumidor.", "verso": "Certo.", "explicacao": "Quem é menos elástico arca com mais o tributo."}, {"id": 2000004464, "trilha": "fiscal", "materia": "eco", "assunto": "Microeconomia", "tipo": "certo_errado", "frente": "Certo ou errado? No monopólio, o preço é igual ao custo marginal.", "verso": "Errado. O monopolista cobra preço acima do custo marginal, produzindo onde receita marginal = custo marginal.", "explicacao": "Gera peso morto."}, {"id": 2000004465, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "certo_errado", "frente": "Certo ou errado? Aumentar a Selic tende a valorizar o real.", "verso": "Certo. Juros maiores atraem capital estrangeiro, aumentando a oferta de dólares.", "explicacao": "Efeito pelo canal do câmbio."}, {"id": 2000004466, "trilha": "fiscal", "materia": "eco", "assunto": "Macroeconomia", "tipo": "certo_errado", "frente": "Certo ou errado? O PIB inclui bens intermediários para evitar distorções.", "verso": "Errado. Inclui só bens e serviços finais, para evitar dupla contagem.", "explicacao": "Ou soma o valor adicionado em cada etapa."}, {"id": 2000004467, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "certo_errado", "frente": "Certo ou errado? A desvalorização do real encarece as importações.", "verso": "Certo.", "explicacao": "E barateia as exportações em moeda estrangeira."}, {"id": 2000004468, "trilha": "fiscal", "materia": "adua", "assunto": "Conceitos", "tipo": "certo_errado", "frente": "Certo ou errado? O imposto de importação incide sobre mercadoria nacional que retorna ao país.", "verso": "Certo, em regra: considera-se estrangeira a mercadoria nacional ou nacionalizada exportada que retorna, salvo exceções (como devolução por defeito).", "explicacao": "Decreto-Lei 37/1966, art. 1º, § 1º."}, {"id": 2000004469, "trilha": "fiscal", "materia": "adua", "assunto": "Conceitos", "tipo": "certo_errado", "frente": "Certo ou errado? As alíquotas do imposto de exportação só podem ser alteradas por lei.", "verso": "Errado. O Executivo pode alterá-las, nos limites da lei (na prática, a Camex).", "explicacao": "CF, art. 153, § 1º."}, {"id": 2000004470, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho", "tipo": "certo_errado", "frente": "Certo ou errado? No canal verde, a mercadoria é desembaraçada sem exame documental e sem verificação física.", "verso": "Certo, embora a Receita possa revê-la depois.", "explicacao": "Parametrização."}, {"id": 2000004471, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "certo_errado", "frente": "Certo ou errado? No regime aduaneiro especial, os tributos são extintos definitivamente na entrada da mercadoria.", "verso": "Errado. Em regra, ficam suspensos, sob condições e prazo, e podem ser exigidos se o regime for descumprido.", "explicacao": "Regulamento Aduaneiro, art. 307."}, {"id": 2000004472, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "certo_errado", "frente": "Certo ou errado? A pena de perdimento só se aplica se houver dolo comprovado.", "verso": "Errado. As infrações aduaneiras, em regra, independem da intenção do agente.", "explicacao": "Decreto-Lei 37/1966, art. 94, § 2º."}, {"id": 2000004473, "trilha": "fiscal", "materia": "adua", "assunto": "Valoração", "tipo": "lacuna", "frente": "\"O primeiro método de valoração aduaneira é o valor de ____.\"", "verso": "transação", "explicacao": "Preço efetivamente pago ou a pagar, com ajustes."}, {"id": 2000004474, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "certo_errado", "frente": "Certo ou errado? A soma dos desvios em relação à média é sempre zero.", "verso": "Certo.", "explicacao": "Por isso se usa o quadrado dos desvios na variância."}, {"id": 2000004475, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "certo_errado", "frente": "Certo ou errado? O desvio padrão pode ser negativo.", "verso": "Errado. É sempre maior ou igual a zero.", "explicacao": "É a raiz quadrada da variância."}, {"id": 2000004476, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "certo_errado", "frente": "Certo ou errado? Eventos mutuamente exclusivos com probabilidade positiva são independentes.", "verso": "Errado. Se um ocorre, o outro não pode ocorrer, então eles são dependentes.", "explicacao": "P(A ∩ B) = 0 ≠ P(A) × P(B)."}, {"id": 2000004477, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "certo_errado", "frente": "Certo ou errado? Não rejeitar H0 prova que ela é verdadeira.", "verso": "Errado. Apenas não há evidência suficiente para rejeitá-la.", "explicacao": "Raciocínio de teste de hipóteses."}, {"id": 2000004478, "trilha": "fiscal", "materia": "est", "assunto": "Regressão", "tipo": "certo_errado", "frente": "Certo ou errado? Correlação igual a zero significa que não há nenhuma relação entre as variáveis.", "verso": "Errado. Significa ausência de relação linear; pode haver relação não linear.", "explicacao": "Coeficiente de Pearson."}, {"id": 2000004479, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "lacuna", "frente": "\"Na distribuição normal padrão, a média é ____ e o desvio padrão é 1.\"", "verso": "0", "explicacao": "Z = (X − μ) ÷ σ."}, {"id": 2000004480, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "certo_errado", "frente": "Certo ou errado? A cláusula WHERE pode filtrar resultados de funções de agregação.", "verso": "Errado. Para filtrar agregações, usa-se HAVING.", "explicacao": "WHERE filtra linhas antes do agrupamento."}, {"id": 2000004481, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "certo_errado", "frente": "Certo ou errado? A chave primária pode ter valores nulos.", "verso": "Errado. Deve ser única e não nula.", "explicacao": "Integridade de entidade."}, {"id": 2000004482, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "certo_errado", "frente": "Certo ou errado? A LGPD só se aplica a dados em meio digital.", "verso": "Errado. Aplica-se a dados pessoais em qualquer meio, físico ou digital.", "explicacao": "LGPD, art. 1º."}, {"id": 2000004483, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "certo_errado", "frente": "Certo ou errado? Dado anonimizado é considerado dado pessoal pela LGPD.", "verso": "Errado, salvo se o processo de anonimização puder ser revertido com esforços razoáveis.", "explicacao": "LGPD, art. 12."}, {"id": 2000004484, "trilha": "fiscal", "materia": "dados", "assunto": "Aprendizado de máquina", "tipo": "certo_errado", "frente": "Certo ou errado? Um modelo com 99% de acurácia é sempre bom.", "verso": "Errado. Em dados desbalanceados (ex.: 1% de fraudes), um modelo que nunca aponta fraude tem 99% de acurácia e é inútil.", "explicacao": "Use também precisão, recall e F1."}, {"id": 2000004485, "trilha": "fiscal", "materia": "dados", "assunto": "Conceitos", "tipo": "lacuna", "frente": "\"Os dados que não seguem um formato fixo, como textos, imagens e vídeos, são chamados de dados não ____.\"", "verso": "estruturados", "explicacao": "Representam a maior parte dos dados atuais."}, {"id": 2000004486, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes", "tipo": "pergunta", "frente": "O que é o regime de admissão temporária para aperfeiçoamento ativo?", "verso": "Entrada de mercadoria estrangeira, com suspensão de tributos, para conserto, reparo, restauração ou industrialização no país, e posterior reexportação.", "explicacao": "Regulamento Aduaneiro, art. 380."}, {"id": 2000004487, "trilha": "fiscal", "materia": "adua", "assunto": "Bagagem", "tipo": "pergunta", "frente": "Quais bens o viajante pode trazer com isenção como bagagem?", "verso": "Bens de uso ou consumo pessoal, livros e periódicos, e outros bens até a cota de isenção, sem finalidade comercial.", "explicacao": "Regulamento Aduaneiro, art. 157, e normas da Receita."}, {"id": 2000004488, "trilha": "fiscal", "materia": "adua", "assunto": "Bagagem", "tipo": "pergunta", "frente": "Qual a alíquota do regime de tributação especial para bagagem que excede a cota?", "verso": "50% sobre o valor que excede a isenção.", "explicacao": "Regime de tributação especial (RTE)."}, {"id": 2000004489, "trilha": "fiscal", "materia": "adua", "assunto": "Controle", "tipo": "pergunta", "frente": "O que é a vigilância aduaneira?", "verso": "Fiscalização da zona primária e da zona secundária para prevenir e reprimir contrabando, descaminho e outras infrações.", "explicacao": "Exercida pela Receita Federal."}, {"id": 2000004490, "trilha": "fiscal", "materia": "adua", "assunto": "Controle", "tipo": "pergunta", "frente": "O que é o Siscomex Carga?", "verso": "Módulo que controla a movimentação de embarcações, cargas e unidades de carga nos portos.", "explicacao": "Registra manifestos e conhecimentos eletrônicos."}, {"id": 2000004491, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "O que é a declaração de responsabilidade da administração na carta de representação?", "verso": "A confirmação de que a administração cumpriu sua responsabilidade pelas demonstrações e forneceu todas as informações ao auditor.", "explicacao": "NBC TA 580."}, {"id": 2000004492, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "As representações formais da administração substituem outras evidências?", "verso": "Não. São evidência necessária, mas não suficiente sozinha.", "explicacao": "NBC TA 580."}, {"id": 2000004493, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é a primeira auditoria (auditoria inicial) e o que exige sobre saldos iniciais?", "verso": "Quando as demonstrações anteriores não foram auditadas ou foram por outro auditor. Exige evidência de que os saldos iniciais não contêm distorções que afetem o período atual.", "explicacao": "NBC TA 510."}, {"id": 2000004494, "trilha": "fiscal", "materia": "aud", "assunto": "Grupo", "tipo": "pergunta", "frente": "O que é a auditoria de demonstrações de grupo?", "verso": "Auditoria das demonstrações consolidadas, em que o auditor do grupo pode usar o trabalho de auditores de componentes, mantendo a responsabilidade pela opinião.", "explicacao": "NBC TA 600."}, {"id": 2000004495, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Como se calcula o intervalo de confiança para uma proporção?", "verso": "p̂ ± z × √[p̂ × (1 − p̂) ÷ n].", "explicacao": "Ex.: p̂ = 0,5, n = 100, 95%: 0,5 ± 1,96 × 0,05."}, {"id": 2000004496, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "O que são graus de liberdade na distribuição t?", "verso": "n − 1 na estimativa da média com uma amostra.", "explicacao": "Com mais graus de liberdade, a t se aproxima da normal."}, {"id": 2000004497, "trilha": "fiscal", "materia": "est", "assunto": "Descritiva", "tipo": "pergunta", "frente": "O que é a curtose?", "verso": "Medida do achatamento da distribuição em relação à normal.", "explicacao": "Leptocúrtica: mais pontiaguda; platicúrtica: mais achatada."}, {"id": 2000004498, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz a função COALESCE?", "verso": "Retorna o primeiro valor não nulo da lista.", "explicacao": "Ex.: COALESCE(telefone, 'sem telefone')."}, {"id": 2000004499, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que faz o comando INSERT INTO ... SELECT?", "verso": "Insere em uma tabela as linhas retornadas por uma consulta.", "explicacao": "Útil para copiar dados entre tabelas."}, {"id": 2000004500, "trilha": "fiscal", "materia": "dados", "assunto": "Governança", "tipo": "pergunta", "frente": "O que é linhagem de dados (data lineage)?", "verso": "O rastreamento da origem dos dados e de todas as transformações que sofreram até o destino.", "explicacao": "Importante para confiabilidade e auditoria."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
